def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to obtain field names and values from common attributes
    if hasattr(self, "_keys") and hasattr(self, "_data"):
        field_names = list(self._keys)
        values = list(self._data)
    elif hasattr(self, "_field_names") and hasattr(self, "_values"):
        field_names = list(self._field_names)
        values = list(self._values)
    elif isinstance(self, dict):
        # If the object is already a dict, just return it
        return dict(self)
    else:
        # Fallback: try to use public attributes as fields
        field_names = [k for k in dir(self) if not k.startswith("_") and not callable(getattr(self, k))]
        values = [getattr(self, k) for k in field_names]

    # Helper to map key to index if key is a string
    key_to_index = {name: idx for idx, name in enumerate(field_names)}

    # If no keys specified, return all fields
    if not keys:
        return dict(zip(field_names, values))

    result = {}
    for k in keys:
        # Handle integer index
        if isinstance(k, int):
            idx = k
            if idx < 0 or idx >= len(field_names):
                raise IndexError(f"Index {idx} out of bounds for record")
            name = field_names[idx]
            result[name] = values[idx]
        else:
            # Treat as field name (string or other hashable)
            if k in key_to_index:
                idx = key_to_index[k]
                result[k] = values[idx]
            else:
                # Insert key with None if not present
                result[k] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    buf_attr = None
    buf = None
    # Find a suitable buffer attribute
    for name in ("buffer", "data", "bytes"):
        if hasattr(self, name):
            buf_attr = name
            buf = getattr(self, name)
            break
    if buf_attr is None or buf is None:
        raise AttributeError("No buffer attribute found on the object")
    if len(buf) < 2:
        raise ValueError("Not enough data to pop u16")
    last_two = buf[-2:]
    if isinstance(buf, bytearray):
        # Modify in place
        del buf[-2:]
    else:
        # For immutable types like bytes, replace the attribute
        setattr(self, buf_attr, buf[:-2])
    return int.from_bytes(last_two, "big")

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer."""
    try:
        # Ensure the stream has a data buffer
        data = self.data
    except AttributeError:
        raise AttributeError("Stream object must have a 'data' attribute")

    if len(data) < 2:
        raise ValueError("Not enough data to pop a 16-bit integer")

    # Extract the last two bytes
    last_two = data[-2:]

    # Remove them from the buffer
    self.data = data[:-2]

    # Convert the bytes to an unsigned integer (big-endian)
    return int.from_bytes(last_two, byteorder="big", signed=False)

