def _inline_r_setup(code: str) -> str:
    r"""
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    # Validate input type
    if not isinstance(code, str):
        raise TypeError(f"_inline_r_setup requires `code` to be a str, got {type(code).__name__}")

    # Typical R options that might need to be set for consistent behaviour
    options_lines = [
        "# Set R options for inline code",
        "options(digits = 10)",          # keep up to 10 significant digits
        "options(scipen = 999)",        # avoid scientific notation
        "options(stringsAsFactors = FALSE)",  # avoid automatic factor conversion
    ]

    # If the code already contains the options, avoid duplication
    stripped_code = code.lstrip()
    for opt in options_lines[1:]:
        opt_str = opt.partition("=")[0].strip()
        if any(line.strip().startswith(opt_str) for line in stripped_code.splitlines()):
            # option already set, skip adding all options again
            return code

    # Build the final code string
    if stripped_code:
        return "\n".join(options_lines + ["", code])
    else:
        # If the provided code is empty or whitespace, just return the options block
        return "\n".join(options_lines)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")

    parts = s.strip().split(".")
    if not parts or parts == [""]:
        return ()

    parsed: list[int] = []
    for part in parts:
        if part == "":
            parsed.append(0)
            continue
        try:
            parsed.append(int(part))
        except ValueError:
            # Try to extract a leading integer from the part
            digits = ""
            for ch in part:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            if digits:
                parsed.append(int(digits))
            else:
                raise ValueError(f"Non-numeric version part: {part!r}") from None
    return tuple(parsed)

