def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """
    Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine.
    """
    if not isinstance(cmd, tuple):
        raise TypeError(f'cmd must be a tuple, got {type(cmd).__name__}')
    try:
        import os
        import sys

        # Make a mutable copy of the command tuple
        newcmd = list(cmd)

        # If the first argument is a script file (e.g. .py/.pyw) and we haven't
        # explicitly invoked the interpreter, prepend sys.executable.
        if newcmd:
            script_path = newcmd[0]
            _, ext = os.path.splitext(script_path)
            if ext.lower() in {'.py', '.pyw'} and not newcmd[0].lower().startswith(('python', 'pythonw', sys.executable.lower())):
                newcmd.insert(0, sys.executable)

        # Ensure that any argument containing whitespace is quoted.  This
        # addresses issues on Windows where the command line splits on spaces.
        for idx, arg in enumerate(newcmd):
            if isinstance(arg, str) and ' ' in arg:
                # Strip any existing surrounding quotes
                stripped = arg.strip('\'"')
                if not (stripped.startswith('\"') and stripped.endswith('\"')):
                    newcmd[idx] = f'"{stripped}"'

        return tuple(newcmd)
    except Exception as exc:
        # Re‑raise with context to avoid hiding the original traceback
        raise RuntimeError('Error normalizing command tuple') from exc

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine

    Args:
        cmd: Tuple of command line arguments, usually a script name followed by its arguments.

    Returns:
        A possibly modified tuple that will run correctly on Windows.
    """
    import os
    import sys
    if not isinstance(cmd, (tuple, list)) or not cmd:
        return tuple(cmd)

    script_path = cmd[0]

    # Attempt to read the shebang line of the script, if the file exists
    try:
        with open(script_path, 'rb') as f:
            first_line = f.readline().decode('utf-8', errors='ignore')
    except Exception:
        # If the file doesn't exist or can't be read, return the original command
        return tuple(cmd)

    # If there is no shebang, no modification is necessary
    if not first_line.startswith('#!'):
        return tuple(cmd)

    # Extract the interpreter part of the shebang
    try:
        # Strip the '#!' and remove any leading/trailing whitespace
        interp_line = first_line[2:].strip()
        # Split into tokens; the first token is the interpreter path,
        # any remaining tokens are arguments passed to the interpreter.
        tokens = interp_line.split()
        if not tokens:
            return tuple(cmd)
        # Handle the common "/usr/bin/env interpreter" pattern
        if os.path.basename(tokens[0]) == 'env':
            if len(tokens) < 2:
                return tuple(cmd)
            interpreter = tokens[1]
            # Preserve any additional env arguments
            env_args = tuple(tokens[2:])
        else:
            interpreter = tokens[0]
            env_args = tuple(tokens[1:])
    except Exception:
        return tuple(cmd)

    # Resolve to an absolute path if necessary
    interpreter_path = os.path.normpath(interpreter)
    if not os.path.isabs(interpreter_path):
        # If the interpreter is not an absolute path, assume it is on the PATH
        # and keep it as is.  Windows shell will locate it automatically.
        pass

    # On Windows, quote the interpreter path if it contains spaces and is not already quoted
    if sys.platform.startswith('win'):
        if ' ' in interpreter_path and not (
            interpreter_path.startswith('"') and interpreter_path.endswith('"')
        ):
            interpreter_path = f'"{interpreter_path}"'

    # Build the new command tuple:
    # [interpreter_path] [interpreter arguments (if any)] [script_path] [original arguments]
    new_cmd = (interpreter_path,) + env_args + (script_path,) + tuple(cmd[1:])
    return new_cmd

