        # Remove all handlers attached to the root logger
        for handler in root_logger.handlers[:]:
            root_logger.removeHandler(handler)
        # Reset the root level to WARNING (default)
        root_logger.setLevel(logging.WARNING)
        # Reinitialize the lastResort handler if it has been removed
        if not root_logger.lastResort:
            root_logger.lastResort = logging.StreamHandler()
            root_logger.lastResort.setLevel(logging.WARNING)
    except Exception as exc:
        # If logging has not been configured yet, silently ignore errors
        pass

