        if getattr(self, "initial_value", None) is not None:
            # preserve current number of bins if any
            bin_count = len(self.bins) if hasattr(self, "bins") else 0
            if bin_count:
                self.bins = [self.initial_value] * bin_count
            else:
                self.bins = self.make_bins()
        else:
            self.bins = self.make_bins()
    except Exception:
        # Fallback to empty bins if something fails
        self.bins = []

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    if separator is None:
        raise ValueError("separator must be a string")

    # Write header if provided
    if header is not None:
        try:
            print(header)
        except Exception as exc:
            raise RuntimeError(f"Failed to write header: {exc}") from exc

    for point in self:
        # Try to get coordinate and value attributes; fall back to tuple unpacking
        coordinate = getattr(point, "coordinate", None)
        value = getattr(point, "value", None)
        if coordinate is None or value is None:
            try:
                coordinate, value = point
            except Exception as exc:
                raise RuntimeError(f"Point {point!r} is not iterable and has no attributes") from exc

        # Convert coordinate parts to string
        coord_parts = []
        if isinstance(coordinate, (list, tuple)):
            for c in coordinate:
                coord_parts.append(str(c))
        else:
            coord_parts.append(str(coordinate))

        # Convert value parts to string
        value_parts = []
        if isinstance(value, (list, tuple)):
            for v in value:
                value_parts.append(str(v))
        else:
            if isinstance(value, str):
                value_parts.append(value)
            elif value is None:
                value_parts.append("")
            else:
                value_parts.append(str(value))

        # Join all parts with the separator and output the line
        line = separator.join(coord_parts + value_parts)
        print(line)

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Prepare container for CSV lines
    lines = []

    # Add optional header
    if header is not None:
        lines.append(str(header))

    # --- Retrieve point iterator -----------------------------------------
    point_iter = None
    try:
        if hasattr(self, "points"):
            point_iter = self.points
    except Exception:
        pass
    if point_iter is None and hasattr(self, "iterate"):
        point_iter = self.iterate

    if point_iter is None:
        raise TypeError(
            "Graph object provides no 'points' or 'iterate' attribute to "
            "obtain graph points."
        )

    # If the provider is a callable, call it without args
    if callable(point_iter):
        try:
            point_iter = point_iter()
        except Exception as exc:
            raise TypeError(f"Failed to call point provider: {exc}") from exc

    # --- Generate CSV lines ----------------------------------------------
    for point in point_iter:
        try:
            # Attempt to split point into coordinate(s) and value(s)
            if isinstance(point, (tuple, list)):
                # Support: (coords, value) or just [coords]
                if len(point) == 2:
                    coords, value = point[0], point[1]
                else:
                    coords, value = point[0], None
            else:
                # Fallback: entire point considered as a single value
                coords, value = point, None

            # Convert coordinates
            if isinstance(coords, (tuple, list)) and not isinstance(coords, (str, bytes)):
                coord_parts = [str(c) for c in coords]
            else:
                coord_parts = [str(coords)]

            # Convert value parts
            val_parts = []
            if value is not None:
                if isinstance(value, (tuple, list)) and not isinstance(value, (str, bytes)):
                    val_parts = [str(v) for v in value]
                else:
                    val_parts = [str(value)]

            # Build CSV line
            line = separator.join(coord_parts + val_parts)
            lines.append(line)
        except Exception:
            # Skip points that cannot be processed
            continue

    # Join all lines into a single string
    return "\n".join(lines) + ("\n" if lines else "")

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    Args:
        separator (str, optional): Delimiter for values. Defaults to ",".
        header (str, optional): Optional header line to prepend. If None, no header is added.

    Returns:
        str: CSV formatted string representing the graph's points.

    Raises:
        ValueError: If a point cannot be interpreted as a (coordinate, value) pair.
    """
    lines = []

    if header is not None:
        lines.append(header)

    for point in self:
        try:
            coord, val = point
        except Exception as exc:
            raise ValueError(f"Point {point!r} is not a (coordinate, value) pair") from exc

        # Convert coordinate
        if isinstance(coord, (tuple, list)):
            coord_str = separator.join(str(x) for x in coord)
        else:
            coord_str = str(coord)

        # Convert value
        if isinstance(val, (tuple, list)):
            val_str = separator.join(str(v) for v in val)
        else:
            val_str = "" if val is None else str(val)

        # If both coordinate and value are empty, skip
        if not coord_str and not val_str:
            continue

        # Combine coordinate and value with separator
        # If value is empty, just output coordinate
        if val_str:
            line = separator.join([coord_str, val_str])
        else:
            line = coord_str
        lines.append(line)

    return "\n".join(lines) + ("\n" if lines else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Verify that we have variables to search
    if not hasattr(self, "_variables") or not isinstance(self._variables, dict):
        raise AttributeError("The caller does not have a '_variables' dictionary to search.")
    err_indices = []

    # Scan through all variables looking for those that match the coordinate name
    # and conventionally indicate an error (e.g., ending with '_err' or containing the
    # coordinate name followed by 'err').
    for var_name, var in self._variables.items():
        # Check naming patterns
        if coord_name in var_name and (var_name.endswith("_err") or var_name.lower().endswith("err")):
            err_indices.append(var_name)

        # If the variable object carries coordinate information we also check that
        # the requested coordinate is part of its coordinate list.
        if hasattr(var, "coords"):
            try:
                coords = var.coords
                # Normalise to a list or tuple
                if isinstance(coords, dict):
                    coord_keys = list(coords.keys())
                else:
                    coord_keys = list(coords)
                if coord_name in coord_keys:
                    # Byte or boolean arrays typically come with an accompanying
                    # coordinate; treat them as errors if they are 1‑D.
                    if getattr(var, "dtype", None) is not None and var.dtype.kind == "b" and var.ndim == 1:
                        err_indices.append(var_name)
            except Exception:
                # Ignore any errors in accessing coordinate information
                pass

    if not err_indices:
        raise KeyError(f"No error indices found for coordinate '{coord_name}'.")
    return err_indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    errors = None
    # Prefer dictionary of errors if available
    if hasattr(self, 'errors') and isinstance(self.errors, dict):
        errors = self.errors.get(coord_name)
    # Fallback to attribute named "<coord_name>_err"
    if errors is None:
        err_attr = f"{coord_name}_err"
        if hasattr(self, err_attr):
            errors = getattr(self, err_attr)
    if errors is None:
        return []
    try:
        iterator = iter(errors)
    except TypeError:
        # Not iterable – cannot determine indices
        return []
    # Collect indices where error value is truthy (non-zero, non-None)
    return [i for i, v in enumerate(iterator) if v]

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Retrieve the error mask or array for the given coordinate name.
        try:
            err = self.errors[coord_name]
        except (AttributeError, KeyError):
            raise ValueError(
                f"No error information available for coordinate '{coord_name}'"
            )

        # Convert to NumPy array for robust indexing.
        try:
            err_arr = np.asarray(err)
        except Exception as exc:
            raise TypeError(
                f"Error data for coordinate '{coord_name}' is not array‑like"
            ) from exc

        # Find indices where the error flag is True.
        indices = np.where(err_arr)[0]

        # Return as a plain Python list for consistency and to avoid
        # returning an empty NumPy array in case of no errors.
        return indices.tolist() if indices.size else []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Attempt to retrieve the error indices from the instance.
    # Most implementations store error indices in a dictionary called
    # `self.errors` that maps coordinate names to lists/arrays of indices.
    try:
        if not hasattr(self, "errors"):
            # No error mapping available
            return []
        err = self.errors.get(coord_name)
        if err is None:
            # No error information for this coordinate
            return []
        # Convert to a plain Python list of indices.
        if isinstance(err, (list, tuple)):
            return list(err)
        # If err is a NumPy array or pandas/ xarray object with a
        # to_numpy or values attribute, try to extract the list.
        try:
            return err.tolist()
        except Exception:
            pass
        try:
            return err.to_numpy().tolist()
        except Exception:
            pass
        # Fallback: try to cast iterable to list
        try:
            return list(err)
        except Exception:
            pass
        # If err is a scalar value, return it as a single-element list
        return [err]
    except Exception:
        # In case of any unexpected error, return an empty list.
        return []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # convert inputs to numpy arrays (assumes np is already imported)
    try:
        bins_arr = np.asarray(bins, dtype=float)
    except Exception as exc:
        raise ValueError("`bins` must be array-like and convertible to numeric") from exc

    try:
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise ValueError("`edges` must be array-like and convertible to numeric") from exc

    # basic dimensionality checks
    if bins_arr.ndim != 1:
        raise ValueError("`bins` must be a one-dimensional array")
    if edges_arr.ndim != 1:
        raise ValueError("`edges` must be a one-dimensional array")

    # edges must have exactly one more element than bins
    if edges_arr.size != bins_arr.size + 1:
        raise ValueError("`edges` length must be one greater than `bins` length")

    # compute bin widths and ensure monotonically increasing edges
    widths = np.diff(edges_arr)
    if np.any(widths < 0):
        raise ValueError("`edges` must be monotonically increasing")

    # integral is sum over bin counts times bin widths
    return np.sum(bins_arr * widths)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Exclude source sequences
        if isinstance(seq, Source):
            return False
        # Directly a single FillRequest instance
        if isinstance(seq, FillRequest):
            return True
        # Handle common built-in sequence types
        if isinstance(seq, (list, tuple, set, frozenset)):
            return any(isinstance(item, FillRequest) for item in seq)
        # General iterable fallback
        return any(isinstance(item, FillRequest) for item in seq)
    except Exception:
        return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences immediately
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class not defined, ignore this check
        pass

    # If seq itself is a FillRequest, it's valid
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class not defined, cannot perform type check
        pass

    # Otherwise, try to iterate over seq and look for any FillRequest element
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is not defined, cannot evaluate this item
                continue
    except TypeError:
        # seq is not iterable
        pass

    return False

