def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    """
    # Normalize level: treat any negative smaller than -1 as infinite recursion
    if level < -1:
        level = -1

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key absent in d2: include as is
            result[key] = val1
        else:
            val2 = d2[key]
            # Both are dictionaries and we can recurse (unless level==0)
            if isinstance(val1, dict) and isinstance(val2, dict) and (level == -1 or level > 0):
                sub_level = level - 1 if level > 0 else -1
                sub_diff = difference(val1, val2, sub_level)
                if sub_diff:
                    result[key] = sub_diff
            else:
                # For non-dict or when recursion not allowed, compare directly
                if val1 != val2:
                    result[key] = val1
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    import copy

    def _diff(a, b, lev):
        result = {}
        for k, v in a.items():
            if k not in b:
                result[k] = copy.deepcopy(v)
                continue

            vb = b[k]
            if isinstance(v, dict) and isinstance(vb, dict):
                if lev == 0:
                    if v != vb:
                        result[k] = copy.deepcopy(v)
                else:
                    sub_res = _diff(v, vb, lev - 1 if lev > 0 else lev)
                    if sub_res:
                        result[k] = sub_res
            else:
                if v != vb:
                    result[k] = copy.deepcopy(v)
        return result

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np

    # Ensure histogram has required attributes
    if not hasattr(self, "edges") or not hasattr(self, "values"):
        raise AttributeError(
            "Histogram object must have 'edges' and 'values' attributes"
        )

    # Convert coord to a NumPy array for consistency
    coord_arr = np.asarray(coord)

    # Support only a single point (1D or multi‑dimensional)
    if coord_arr.ndim == 0:
        # Scalar coordinate, interpret as 1‑D histogram
        coord_arr = coord_arr.reshape(1)

    # If coordinate array has more than one dimension, treat each dimension as a bin edge axis
    if isinstance(self.edges, list):
        # Multi‑dimensional histogram
        if coord_arr.ndim != 1:
            raise ValueError(
                "Coordinate must be a 1‑D array matching the number of edges"
            )
        if len(coord_arr) != len(self.edges):
            raise ValueError(
                f"Coordinate dimension ({len(coord_arr)}) does not match histogram edges ({len(self.edges)})"
            )

        bin_indices = []
        for dim, val in enumerate(coord_arr):
            edges_dim = np.asarray(self.edges[dim])
            idx = np.searchsorted(edges_dim, val, side="right") - 1

            # If out of bounds, ignore the point
            if idx < 0 or idx >= len(edges_dim) - 1:
                return

            bin_indices.append(idx)

    else:
        # 1‑D histogram
        edges = np.asarray(self.edges)
        if coord_arr.ndim != 1:
            raise ValueError("Coordinate must be a 1‑D array for 1‑D histogram")
        idx = np.searchsorted(edges, coord_arr[0], side="right") - 1

        if idx < 0 or idx >= len(edges) - 1:
            return

        bin_indices = [idx]

    # Safely add the weight, converting it to a scalar if possible
    try:
        # Attempt a broadcast; this works if weight is a scalar or matches shape
        self.values[tuple(bin_indices)] += weight
    except Exception as exc:
        # If addition fails (e.g., mismatched shapes), raise a clear error
        raise ValueError(
            f"Failed to add weight to histogram bin {tuple(bin_indices)}: {exc}"
        )

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Ensure histogram attributes exist
        if not hasattr(self, 'edges') or not hasattr(self, 'data'):
            raise AttributeError("Histogram must have 'edges' and 'data' attributes.")
        # Convert to array for consistency
        coord_arr = np.asarray(coord)
        if coord_arr.ndim > 1:
            coord_arr = coord_arr.reshape(-1)
        # Find bin indices: right edge inclusion
        bin_idx = np.searchsorted(self.edges, coord_arr, side='right') - 1
        # Mask valid indices
        valid = (bin_idx >= 0) & (bin_idx < self.data.size)
        if not np.any(valid):
            return  # nothing to do
        # Handle weight: broadcast or array
        try:
            weight_arr = np.asarray(weight)
        except Exception:
            weight_arr = np.full_like(coord_arr, weight, dtype=float)
        if np.isscalar(weight):
            self.data[bin_idx[valid]] += weight
        else:
            # Ensure shape compatibility
            if weight_arr.shape != coord_arr.shape:
                weight_arr = np.broadcast_to(weight_arr, coord_arr.shape)
            self.data[bin_idx[valid]] += weight_arr[valid]

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Define permitted regex patterns for keys and values.
    # The exact patterns can be modified to match the real application's requirements.
    KEY_REGEX = r'^[A-Za-z0-9_\-]+$'
    VALUE_REGEX = r'^[A-Za-z0-9_\-]+$'

    key_pattern = re.compile(KEY_REGEX)
    value_pattern = re.compile(VALUE_REGEX)

    errors = []

    for key, value in labels.items():
        # Validate the key.
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(key):
                errors.append(
                    {str(key): f"Label key '{key}' does not match the regex [{KEY_REGEX}]"}
                )

        # Validate the value.
        if isinstance(value, (list, tuple)):
            if not value:
                # Empty list is considered invalid: treat as non string item.
                errors.append({str(value): 'expected string or bytes-like object'})
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
