            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Helper function to check key/value against a simple regex: alphanumeric, underscore or hyphen.
    def _is_valid_regex(s):
        return all((c.isalnum() or c in ("_", "-")) for c in s)

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Validate key format
            key_str = key if isinstance(key, str) else key.decode()
            if not _is_valid_regex(key_str):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value type; allow list/tuple of values
        if isinstance(value, (list, tuple)):
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    errors.append({str(elem): "expected string or bytes-like object"})
                else:
                    elem_str = elem if isinstance(elem, str) else elem.decode()
                    if not _is_valid_regex(elem_str):
                        errors.append({elem: f"Label value '{elem}' does not match the regex [...]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): "expected string or bytes-like object"})
            else:
                val_str = value if isinstance(value, str) else value.decode()
                if not _is_valid_regex(val_str):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    The pattern follows the common Kubernetes DNS subdomain conventions:
    * lowercase alphanumeric characters are required,
    * hyphens may appear in the middle but not at the start or end,
    * length up to 63 characters.

    Returns:
        (re.Pattern): the compiled regular expression for resource name validation.
    """
    try:
        pattern = r'^[a-z]([-a-z0-9]*[a-z0-9])?$'
        return re.compile(pattern)
    except re.error as exc:
        # Fallback: accept any non-empty string; unlikely to happen
        return re.compile(r'^.+$')

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, str):
        raise ValidationError(f"Value must be a string, got {type(value).__name__}")

    try:
        pattern = re.compile(PATTERN)
    except NameError as exc:
        raise ValidationError("No regex pattern defined for validation.") from exc

    if not pattern.fullmatch(value):
        raise ValidationError(f"Value {value!r} does not match the required pattern.")

def validate_value(value):
    """Validate the given value against the corresponding regular expression."""
    if not isinstance(value, str):
        raise ValidationError("Value must be a string")
    # Basic pattern: allow letters, digits, underscores, hyphens, dots, pluses, and @
    pattern = r'^[\w@.+-]+$'
    if not re.match(pattern, value):
        raise ValidationError(f"'{value}' does not match the required pattern")
    return value

