    resource), the values of the identifying fields are copied from the manifest file.

    """
    # Helper to handle metadata fields at the top level.
    def _handle_metadata(meta):
        result = {}
        # Keep only name, namespace and uid as identifying fields.
        for key in ("name", "namespace", "uid"):
            if key in meta:
                result[key] = meta[key]
            else:
                result[key] = None
        return result

    def _recursive_build(obj, is_top):
        # If we are at the top and encountering identifying keys we keep the value,
        # otherwise we set to None.
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if isinstance(v, dict):
                    if is_top and k == "metadata":
                        new_dict[k] = _handle_metadata(v)
                    else:
                        new_dict[k] = _recursive_build(v, False)
                elif isinstance(v, list):
                    new_list = []
                    for item in v:
                        if isinstance(item, (dict, list)):
                            new_list.append(_recursive_build(item, False))
                        else:
                            # For non-dict/list elements simply place a placeholder.
                            new_list.append(None)
                    new_dict[k] = new_list
                else:
                    # Primitive value.
                    if is_top and k in ("apiVersion", "kind"):
                        new_dict[k] = v
                    else:
                        new_dict[k] = None
            return new_dict
        elif isinstance(obj, list):
            return [
                _recursive_build(elem, False) if isinstance(elem, (dict, list))
                else None
                for elem in obj
            ]
        else:
            return None

    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")
    return _recursive_build(manifest_dict, first_level)

