def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Basic type checking to avoid obscure bugs
    if not isinstance(observer_schema, (list, tuple)):
        raise TypeError("observer_schema must be a list or tuple")
    if not isinstance(response, (dict, list, tuple)):
        raise TypeError("response must be a dict or list-like")

    # Helper to normalise a value that might be missing
    def _init_missing(field_name, resp_value=None):
        if field_name not in last_applied_manifest:
            last_applied_manifest[field_name] = resp_value

    # If the schema expects a dict of values, fall back to the dict helper
    if isinstance(observer_schema, (dict,)):
        raise ValueError("Expected list/tuple for observer_schema, got dict")

    # Iterate over each field descriptor in the schema
    for field in observer_schema:
        # A field can be specified as a string (simple key)
        # or as a dict with more detail (e.g., nested schema)
        if isinstance(field, str):
            field_name = field
            nested_schema = None
        elif isinstance(field, dict):
            field_name = field.get("name")
            nested_schema = field.get("schema")
        else:
            # Unsupported schema definition
            continue

        # Defensive: skip if field_name is None
        if field_name is None:
            continue

        # If there is a nested schema we need to recurse
        if nested_schema is not None:
            # Grab the current sub-object; create if missing
            sub_current = last_applied_manifest.get(field_name)
            if not isinstance(sub_current, (dict, list)):
                sub_current = {}
                last_applied_manifest[field_name] = sub_current

            # Grab the corresponding part of the response; create if missing
            sub_resp = (
                response.get(field_name)
                if isinstance(response, dict)
                else {}
            )
            # Recurse into the nested handler, choosing list or dict
            if isinstance(nested_schema, list):
                update_last_applied_manifest_list_from_resp(
                    sub_current, nested_schema, sub_resp
                )
            elif isinstance(nested_schema, dict):
                update_last_applied_manifest_dict_from_resp(
                    sub_current, nested_schema, sub_resp
                )
            else:
                # Unsupported nested schema type
                continue
        else:
            # No nested schema: simply ensure the field is initialized
            if isinstance(response, dict):
                _init_missing(field_name, response.get(field_name))
            else:
                # If response is not a dict, set to None
                _init_missing(field_name)
    # No return value – mutation in place
    return None

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively updates a list-based ``last_applied_manifest`` from a partial
    Kubernetes response. It iterates over the observer schema, initializing any
    missing fields for each item in the list. Nested structures are handled by
    delegating to the dict‑level helper or by itself.

    Args:
