        elem = last_applied_manifest[idx]
        if not isinstance(elem, dict):
            elem = {}
            last_applied_manifest[idx] = elem

        # Initialize if missing
        if key not in elem:
            elem[key] = resp_val

        # Recursively handle nested structures
        if children is not None:
            try:
                target_val = elem[key]
                # If the scheme indicates a nested list
                if isinstance(children, list) and isinstance(target_val, list):
                    update_last_applied_manifest_list_from_resp(
                        target_val, children, resp_val if isinstance(resp_val, list) else []
                    )
                # If the scheme indicates a nested dict
                else:
                    nested_dict = target_val if isinstance(target_val, dict) else {}
                    # Assume there is a helper for dict updates
                    update_last_applied_manifest_dict_from_resp(
                        nested_dict, children, resp_val if isinstance(resp_val, dict) else {}
                    )
