                # Overwrite with a new dict if current value is not a dict
                nested_last = {}
                last_applied_manifest[field] = nested_last
            if not isinstance(value, dict):
                # If the API returns a non-dict for a nested schema,
                # we simply store the value as is
                last_applied_manifest[field] = value
            else:
                update_last_applied_manifest_dict_from_resp(nested_last, field_schema, value)
        else:
            # For scalar values or lists, simply set/overwrite the value
            last_applied_manifest[field] = value

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")

    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, child_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field '{key}' missing in response")

        resp_value = response[key]

        # If the child schema indicates a nested dictionary, recurse into it
        if isinstance(child_schema, dict):
            nested_last = last_applied_manifest.get(key)
            if nested_last is None:
                nested_last = {}
                last_applied_manifest[key] = nested_last
            if not isinstance(resp_value, dict):
                raise TypeError(f"Expected a dict for field '{key}', got {type(resp_value).__name__}")
            update_last_applied_manifest_dict_from_resp(
                nested_last, child_schema, resp_value
            )

        # If the child schema indicates a list of items, let the list handler
        # take care of it. We simply ensure the key exists in the manifest.
        elif isinstance(child_schema, list):
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], list):
                last_applied_manifest[key] = []
            if not isinstance(resp_value, list):
                raise TypeError(f"Expected a list for field '{key}', got {type(resp_value).__name__}")

        # For primitive values, set the value only if the key does not exist
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = resp_value

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure we have a spec and a manifest to work with
    spec = getattr(app, "spec", None)
    if spec is None:
        return
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        return

    # Retrieve the existing observers dictionary; create it if it doesn't exist
    observers = getattr(spec, "observers", None)
    if observers is None or not isinstance(observers, dict):
        observers = {}
    # Default schema template
    default_schema = {"type": "object"}
    # Determine the list of resources in the manifest
    try:
        # The manifest may be a dict containing an 'items' list, or it could be a list itself
        if isinstance(manifest, dict):
            resources = list(manifest.get("items", []))
        elif isinstance(manifest, (list, tuple)):
            resources = list(manifest)
        else:
            resources = []
    except Exception:
        resources = []

    # Generate default observer schemas for resources lacking one
    for resource in resources:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        if kind not in observers:
            observers[kind] = default_schema

    # Assign the updated observers back to the spec
    try:
        setattr(spec, "observers", observers)
    except Exception:
        pass
    # No explicit return value needed – the function mutates the application object in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
