    except AttributeError:
        return

    # Ensure an observers container exists on the spec
    observers = getattr(spec, "observers", None)
    if observers is None:
        observers = {}
        setattr(spec, "observers", observers)

    # Iterate over the resources in the manifest
    for resource in manifest:
        # Resource must be a mapping
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        if not kind:
            continue

        # If no custom observer schema is defined for this kind, generate a default
        if kind not in observers or not observers.get(kind):
            # Build a very simple default schema:
            # For now we just expose the `metadata.name` as the identifier
            # and watch the entire `status` object.  The exact shape may
            # vary depending on the rest of the application, but this
            # provides a reasonable fallback that can be extended later.
            default_schema = {
                "kind": kind,
                "namespace": resource.get("metadata", {}).get("namespace"),
                "name": "*",
                "status": {
                    "wildcard": True  # indicate that all status fields should be observed
                },
            }
            observers[kind] = default_schema
    # No explicit return needed – the observers are attached to the app spec.

