def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("The 'app' argument must not be None")

    # Ensure the object has the attributes we need
    try:
        spec = app.spec
    except AttributeError:
        raise AttributeError("The provided app does not have a 'spec' attribute")

    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise AttributeError("The spec object does not contain a 'manifest' attribute")

    # Retrieve an existing observer schema mapping, if present
    existing = getattr(spec, "observer_schema", {})
    if existing is None:
        existing = {}

    def _default_schema(res):
        """Create a minimal observer schema from a Kubernetes resource dict."""
        kind = res.get("kind")
        api_version = res.get("apiVersion")
        name = res.get("metadata", {}).get("name")
        return {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {"name": name},
        }

    default_schemas = {}

    # Handle dict or list style manifests
    if isinstance(manifest, dict):
        for key, res in manifest.items():
            res_name = key
            if res_name not in existing:
                default_schemas[res_name] = _default_schema(res)
    elif isinstance(manifest, (list, tuple)):
        for res in manifest:
            res_name = res.get("metadata", {}).get("name")
            if res_name and res_name not in existing:
                default_schemas[res_name] = _default_schema(res)
    else:
        raise TypeError("spec.manifest must be a dict or a list of resource dictionaries")

    # Attach the newly created default schemas to the spec observer_schema map
    if getattr(spec, "observer_schema", None) is None:
        spec.observer_schema = {}
    spec.observer_schema.update(default_schemas)

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate input
    if app is None:
        raise ValueError("app must not be None")
    if not hasattr(app, "spec"):
        raise AttributeError("app object does not have a 'spec' attribute")
    spec = app.spec
    if not hasattr(spec, "manifest"):
        raise AttributeError("app.spec does not have a 'manifest' attribute")
    manifest = spec.manifest
    if not isinstance(manifest, list):
        raise TypeError("app.spec.manifest must be a list of Kubernetes resources")

    # Existing observer schema mapping, if any
    existing_schema = getattr(spec, "observer_schema", {})
    if not isinstance(existing_schema, dict):
        existing_schema = {}

    # Build a mapping of kind to default schema
    default_schema = {}
    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        # Skip if custom schema already defined
        if kind in existing_schema:
            continue
        # Default observer schema can be a minimal spec that matches the kind
        # Here we use a simple placeholder: just specify the kind and
        # api_version from the resource, assuming the observer only cares
        # about the existence of a resource with the same kind and API version.
        api_version = resource.get("apiVersion", "")
        default_schema[kind] = {
            "match": {
                "apiVersion": api_version,
                "kind": kind
            },
            "selectors": [
                {
                    "kind": kind,
                    "apiVersion": api_version
                }
            ]
        }

    # Merge existing schema with new defaults
    merged_schema = dict(existing_schema)
    merged_schema.update(default_schema)

    # Set the merged schema back on the application spec
    spec.observer_schema = merged_schema

    return merged_schema

