    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve the path using the existing path_exists utility
        resolved_path = path_exists(path, allow_empty=False)
    except Exception:
        return False

    try:
        # If the instance has a dedicated validation helper use it
        if hasattr(self, "_check_ocfl_object"):
            self._check_ocfl_object(resolved_path)
        else:
            # Basic structural checks for an OCFL object
            import os
            if not os.path.isdir(resolved_path):
                return False
            # required directories
            content_dir = os.path.join(resolved_path, "content")
            if not os.path.isdir(content_dir):
                return False
            # required metadata/root files
            manifest = os.path.join(content_dir, "manifest")
            if not os.path.exists(manifest):
