def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Attempt to resolve pyfs root or a string path
        if hasattr(path, 'opendir'):
            # Unsupported pyfs type for simplicity; return False
            return False
        root = os.path.realpath(path)
    except Exception:
        return False

    if not root or not os.path.isdir(root):
        return False

    # Common OCFL indicators: an 'objects' directory,
    # a .ocfl-version file, or an object.json descriptor
    objects_dir = os.path.join(root, 'objects')
    ocfl_file = os.path.join(root, '.ocfl-version')
    ocfl_json = os.path.join(root, 'object.json')

    if os.path.isdir(objects_dir):
        return True
    if os.path.isfile(ocfl_file):
        return True
    if os.path.isfile(ocfl_json):
        return True

    return False

