        )

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance (or at least has the same API)
    if not hasattr(prior, 'inventory_version'):
        raise TypeError('prior must be an InventoryValidator-like object with an inventory_version attribute')

    # Check that prior inventory version is older than self's inventory version
    try:
        if prior.inventory_version >= getattr(self, 'inventory_version', None):
            raise ValueError(
                f"prior inventory version ({prior.inventory_version}) must be less than current inventory "
                f"version ({getattr(self, 'inventory_version', 'unknown')})"
            )
    except AttributeError as exc:
        # If either object lacks inventory_version we skip the version comparison
        raise ValueError(f'Cannot compare inventory versions: {exc}')

    # Define the attributes that must be identical (or compatible) between self and prior
    attributes_to_check = ['species', 'parameters', 'stoichiometry_matrix', 'propensities']

    for attr in attributes_to_check:
        if not hasattr(self, attr) or not hasattr(prior, attr):
            raise AttributeError(
                f'Attribute {attr!r} missing from one of the inventories in the comparison'
            )
        base_val = getattr(self, attr)
        prior_val = getattr(prior, attr)

        # For iterables like lists or tuples: compare content after converting to set
        if isinstance(base_val, (list, tuple, set)):
            if set(base_val) != set(prior_val):
                raise ValueError(
                    f'Attribute {attr!r} differs between current and prior inventory'
                )
        # For dictionary-like structures, compare keys and values
        elif isinstance(base_val, dict):
            if base_val.keys() != prior_val.keys():
                raise ValueError(
                    f'Attribute {attr!r} keys differ between current and prior inventory'
                )
            for key in base_val:
                if base_val[key] != prior_val[key]:
                    raise ValueError(
                        f'Attribute {attr!r}[{key!r}] differs between current and prior inventory'
                    )
        # For matrix-like objects, rely on __eq__ or identity; if they support shape, compare shapes
        elif hasattr(base_val, 'shape') and hasattr(prior_val, 'shape'):
            if base_val.shape != prior_val.shape:
                raise ValueError(
                    f'Attribute {attr!r} shape mismatch: current {base_val.shape}, prior {prior_val.shape}'
                )
            # If neither object defines a direct equality comparison, fall back to element-wise check
            try:
                if base_val != prior_val:
                    raise ValueError(
                        f'Attribute {attr!r} values differ between current and prior inventory'
                    )
            except Exception:
                # If comparison fails due to unsupported types, skip detailed check
                pass
        else:
            # For any other type, use direct equality
            if base_val != prior_val:
                raise ValueError(
                    f'Attribute {attr!r} differs between current and prior inventory'
                )

    # If we made it here, the prior inventory passes all checks
    return True

