            content = entry.get("content_file") or entry.get("content_files")
        elif isinstance(entry, (list, tuple)):
            if len(entry) >= 2:
                logical_path, content = entry[0], entry[1]
        if logical_path is None or content is None:
            return
        if not isinstance(content, (list, set, tuple)):
