def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        Mapping from XML basename (without extension) to a list of file
        paths belonging to the same package (i.e., sharing the same
        basename). Only files directly contained in *folder* are considered.
    """
    # Basic validation
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The folder '{folder}' does not exist or is not a directory")

    package_map = {}
    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if not os.path.isfile(full_path):
                continue
            _, ext = os.path.splitext(entry)
            if ext.lower() != ".xml":
                continue
            base_name = os.path.splitext(entry)[0]
            # Group all files with the same base name (case-sensitive)
            related_files = []
            for candidate in os.listdir(folder):
                if not candidate.lower().startswith(base_name.lower()):
                    continue
                if os.path.isfile(os.path.join(folder, candidate)):
                    related_files.append(os.path.join(folder, candidate))
            package_map[base_name] = related_files
        return package_map
    except Exception as e:
        # In case of unexpected errors, return an empty dict but log
        # the exception internally
        return {}

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder)}")
    if not os.path.isdir(folder):
        raise RuntimeError(f"Folder does not exist: {folder}")

    files_by_base = {}

    # Walk through the folder recursively, collecting file paths by their basename (without extension)
    for root, dirs, files in os.walk(folder):
        for fname in files:
            if fname.startswith('.'):  # skip hidden files
                continue
            base, ext = os.path.splitext(fname)
            key = base
            full_path = os.path.join(root, fname)
            files_by_base.setdefault(key, []).append((ext.lower(), full_path))

    # Build the resulting dictionary
    result = {}
    for base, file_entries in files_by_base.items():
        xml_content = None
        related_files = []
        for ext, path in file_entries:
            if ext == '.xml':
                try:
                    tree = ET.parse(path)
                    # Convert the XML tree to a simple dict {tag: text}
                    xml_content = {elem.tag: elem.text for elem in tree.iter()}
                except Exception:
                    xml_content = None
            else:
                related_files.append(path)

        result[base] = {
            'xml': xml_content,
            'files': related_files
        }

    return result

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo a ser analisado

    Returns
    -------
    dict
        dicionário contendo o tipo ('asset' ou 'rendition') e o caminho do arquivo.
    """
    import os

    result = {}
    try:
        base_name = os.path.basename(file_path)
        name_no_ext, ext = os.path.splitext(base_name)
        ext = ext.lower()

        asset_exts = {'.jpg', '.jpeg', '.png', '.bmp', '.gif', '.tiff'}
        rendition_exts = {'.mp4', '.mov', '.avi', '.mkv', '.flv', '.wmv'}

        if ext in asset_exts:
            file_type = 'asset'
        elif ext in rendition_exts:
            file_type = 'rendition'
        else:
            # fallback: look for common pattern in the file name
            name_lc = name_no_ext.lower()
            if 'rendition' in name_lc or 'rend' in name_lc:
                file_type = 'rendition'
            else:
                # if the file shares the same prefix as XML reference, assume asset
                if name_lc.startswith(prefix.lower()):
                    file_type = 'asset'
                else:
                    # Default to asset if uncertain
                    file_type = 'asset'

        result = {'type': file_type, 'file': file_path}

    except Exception:  # pragma: no cover
        # In case of any unexpected error, return an empty dict
        result = {}

    return result

def add_asset(self, basename, file_path):
        """
        {
            "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
            "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
            "artigo02-gf03.png": "/path/artigo02-gf03.png",
        }
        """
        if not isinstance(basename, str):
            raise TypeError("basename must be a string")
        if not isinstance(file_path, str):
            raise TypeError("file_path must be a string")
        if not os.path.isdir(file_path):
            raise FileNotFoundError(f"Directory not found: {file_path}")

        extensions = ['.tiff', '.jpg', '.png']
        assets = {}
        for ext in extensions:
            filename = f"{basename}{ext}"
            full_path = os.path.join(file_path, filename)
            if os.path.isfile(full_path):
                assets[filename] = full_path
            else:
                # Optional: warn or skip. Here we raise to enforce presence.
                raise FileNotFoundError(f"Required asset missing: {full_path}")

        return assets

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Ensure the source file exists
    if not os.path.isfile(file_path):
        raise FileNotFoundError(
            u("Source file does not exist: {0}").format(file_path))

    # Ensure the asset directory exists
    asset_dir = getattr(self, "_asset_path", None)
    if asset_dir is None:
        raise RuntimeError(u("_asset_path attribute is not set"))
    if not os.path.isdir(asset_dir):
        try:
            os.makedirs(asset_dir, exist_ok=True)
        except Exception as exc:
            raise RuntimeError(
                u("Failed to create asset directory {0}: {1}").format(asset_dir, exc))

    # Resolve the target path
    target_path = os.path.join(asset_dir, basename)

    # Avoid overwriting existing assets unless explicitly overridden
    if os.path.exists(target_path):
        raise FileExistsError(
            u("Asset with name {0} already exists at {1}").format(basename, target_path))

    # Copy the file to the asset directory
    try:
        shutil.copyfile(file_path, target_path)
    except Exception as exc:
        raise RuntimeError(
            u("Failed to copy {0} to {1}: {2}").format(file_path, target_path, exc))

    return target_path

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not zip_path:
        return {}
    import zipfile
    import os
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                filename = zinfo.filename
                if not filename.lower().endswith('.xml'):
                    continue
                base = os.path.splitext(os.path.basename(filename))[0]
                try:
                    content = zin.read(filename)
                except Exception:
                    continue
                if base in result:
                    result[base].append(content)
                else:
                    result[base] = [content]
    except (FileNotFoundError, zipfile.BadZipFile):
        pass
    return result

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First collect all XML files to establish grouping keys
            xml_infos = [
                info for info in zf.infolist()
                if not info.is_dir() and info.filename.lower().endswith('.xml')
            ]
            for xml_info in xml_infos:
                base_name = os.path.splitext(os.path.basename(xml_info.filename))[0]
                key = os.path.join(os.path.dirname(xml_info.filename), base_name)
                if key not in result:
                    result[key] = {}
                # Read XML content
                try:
                    result[key][xml_info.filename] = zf.read(xml_info)
                except Exception:
                    # If reading the file fails, skip this entry
                    pass

            # Now add any other files that share the same key (directory + basename)
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base_name = os.path.splitext(os.path.basename(info.filename))[0]
                key = os.path.join(os.path.dirname(info.filename), base_name)
                if key in result and info.filename not in result[key]:
                    try:
                        result[key][info.filename] = zf.read(info)
                    except Exception:
                        pass
    except (FileNotFoundError, zipfile.BadZipFile):
        # Return empty dict if file not found or is not a valid zip
        return {}

    return result

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    # Validate input
    if not isinstance(zip_path, str) or not zip_path:
        raise ValueError("zip_path must be a non-empty string")
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue
                filename = info.filename
                # Determine group key based on XML basename
                base_name, _ext = os.path.splitext(os.path.basename(filename))
                key = os.path.join(os.path.dirname(filename), base_name)
                if key not in result:
                    result[key] = {}
                try:
                    content = zf.read(info)
                except Exception:
                    # If reading fails, store None
                    content = None
                result[key][filename] = content
    except (zipfile.BadZipFile, OSError) as exc:
        raise ValueError(f"Failed to read zip file '{zip_path}': {exc}")

    return result

