def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    import pprint
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if indent < 0:
        raise ValueError("indent must be non-negative")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")
    try:
        formatted = pprint.pformat(self, indent=indent, width=80, compact=True)
    except Exception:
        formatted = str(self)
    if debug:
        debug_header = f"(object at 0x{id(self):x} type {type(self).__name__})\n"
        formatted = debug_header + formatted
    return formatted

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # NOTE: This implementation assumes that the expressions are sympy
    # Boolean expressions.  It uses the built‑in simplify & subsumption
    # methods to apply absorption rules.  If a different representation
    # is used, the logic should be adapted accordingly.
    from sympy import simplify_logic
    new_args = []
    # First simplify all individual expressions
    simplified = [simplify_logic(arg) for arg in args]
    # Remove duplicates
    uniq = []
    seen = set()
    for expr in simplified:
        key = expr.simplify()
        if key not in seen:
            seen.add(key)
            uniq.append(expr)
    # Apply absorption pairs
    for i, a in enumerate(uniq):
        absorbed = False
        for j, b in enumerate(uniq):
            if i == j:
                continue
            # check for A & (A | B) => A
            try:
                if a.func is sympy.And and b.func is sympy.Or:
                    # attempt to test if a = A and b = (A | B)
                    for term_a in a.args:
                        # find a matching term in b
                        if any(term_a == tag for tag in b.args):
                            absorbed = True
                            break
                # check for A | (A & B) => A
                if a.func is sympy.Or and b.func is sympy.And:
                    for term_a in a.args:
                        if any(term_a == tag for tag in b.args):
                            absorbed = True
                            break
                # negative absorption: A & (~A | B) => A & B
                if a.func is sympy.And and b.func is sympy.Or:
                    for term_a in a.args:
                        if term_a.is_Not and term_a.args[0] in b.args:
                            # replace a with a & some other part of b
                            pass
            except Exception:
                continue
            if absorbed:
                break
        if not absorbed:
            new_args.append(a)
    return new_args

