    default = "unknown"
    try:
        # Prefer importlib.metadata (Python 3.8+), otherwise fall back to pkg_resources
        try:
            import importlib.metadata as importlib_metadata
        except Exception:  # pragma: no cover
            from importlib_metadata import metadata as importlib_metadata

        # Use the root package name from this module's namespace
        package_name = __name__.split('.')[0] or None
        if package_name:
            return importlib_metadata.version(package_name)
    except Exception:
        pass

    # As a last resort, try to read a VERSION file in the current directory
    try:
        with open("VERSION", "r", encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        return default

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters:
        pieces (Iterable): An iterable of version components (strings or
            integers). Each component will be converted to a string.
        style (str): The rendering style. Supported styles are:
            * 'numeric' - joined by '.' (e.g., '1.2.3')
            * 'comma'   - joined by ', ' (e.g., '1, 2, 3')
            * 'json'    - JSON array representation
            * 'plain'   - joined by a single space (e.g., '1 2 3')
            * 'short'   - first two components joined by '.' (e.g., '1.2')

    Returns:
        str: The formatted version string.

    Raises:
        TypeError: If pieces is not an iterable.
        ValueError: If style is unsupported or pieces is empty.
    """
    # Validate pieces
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError(f"pieces must be an iterable, got {type(pieces).__name__}")

    # Convert pieces to strings and collect them
    try:
        component_strs = [str(p) for p in iterator]
    except Exception as exc:
        raise ValueError(f"Error converting version pieces to strings: {exc}")

    if not component_strs:
        raise ValueError("pieces must contain at least one component")

    # Normalize style
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")
    style = style.strip().lower()

    if style == 'numeric':
        return '.'.join(component_strs)
    elif style == 'comma':
        return ', '.join(component_strs)
    elif style == 'plain':
        return ' '.join(component_strs)
    elif style == 'short':
        # Short style uses the first two components, if available
        return '.'.join(component_strs[:2])
    elif style == 'json':
        import json
        return json.dumps(component_strs)
    else:
        raise ValueError(f"Unsupported style '{style}'. "
                         f"Supported styles are: numeric, comma, plain, short, json.")

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces is None:
        return ''
    try:
        # Normalize pieces into a list of strings.
        normalized = []
        for piece in pieces:
            # If the piece is a key/value pair, use only the value.
            if isinstance(piece, (tuple, list)) and len(piece) == 2:
                _, value = piece
            else:
                value = piece
            normalized.append(str(value))
    except Exception as exc:
        raise ValueError(f"Invalid pieces sequence: {exc}") from exc

    if style == 'short':
        # Return only the first two components (e.g., major.minor).
        output = ".".join(normalized[:2])
    elif style == 'full':
        # Return all components separated by dots.
        output = ".".join(normalized)
    elif style == 'pretty':
        # Human‑friendly representation like: "Version 1.2.3-beta".
        if len(normalized) >= 3:
            major, minor, patch = normalized[:3]
            extra = "-".join(normalized[3:]) if len(normalized) > 3 else ''
            output = f"Version {major}.{minor}.{patch}{('-' + extra) if extra else ''}"
        else:
            output = ".".join(normalized)
    elif style == 'debug':
        # Show the full Python representation for troubleshooting.
        output = str(normalized)
    else:
        raise ValueError(
            f"Unsupported style '{style}'. "
            f"Supported styles: short, full, pretty, debug."
        )
    return output

