    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    # Append arguments, normalising the same way
    if args:
        if isinstance(args, (list, tuple)):
            cmd_list += list(args)
        else:
            cmd_list.append(args)

    # Optionally print the command for debugging purposes
    if verbose:
        print("Running command:", " ".join(cmd_list))

    # Capture or hide stderr on demand
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Execute the command, propagating environments and cwd if provided
    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result
    except subprocess.CalledProcessError as e:
        # If stderr was not hidden, let the error message be visible
        if not hide_stderr:
            print(f"Command '{' '.join(cmd_list)}' failed with return code {e.returncode}")
