def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    import os
    try:
        # Import the VersioneerConfig class from the versioneer module
        from versioneer import VersioneerConfig
    except Exception as exc:
        raise RuntimeError(
            f"Unable to import VersioneerConfig from versioneer: {exc}"
        ) from exc

    # Instantiate the configuration object
    config = VersioneerConfig()

    # Default configuration values (can be overridden by environment variables)
    defaults = {
        "VCS": os.getenv("VCS", "git"),
        "versionfile_source": os.getenv(
            "VERSIONFILE_SOURCE", "src/<package>/_version.py"
        ),
        "tagprefix": os.getenv("TAGPREFIX", ""),
        "parentdir_prefix_version": os.getenv("PARENTDIR_PREFIX_VERSION", ""),
        "search_parent_directories": os.getenv("SEARCH_PARENT_DIRECTORIES", True),
    }

    # Populate the config object only with attributes that actually exist
    for key, value in defaults.items():
        if hasattr(config, key):
            setattr(config, key, value)

    return config

