def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine how to iterate over objects in the hierarchy.
    # The class is expected to provide an ``_objects`` iterable or method that yields
    # each object in the storage root hierarchy.
    if not hasattr(self, "_objects"):
        raise AttributeError("The object does not provide a '_objects' attribute or method to iterate over hierarchy items.")

    # Counters for results.
    num_objects = 0
    good_objects = 0

    # Helper to log warning messages if a logger is available; otherwise fallback to print.
    def _log_warning(msg):
        logger = getattr(self, "_logger", None)
        if logger and hasattr(logger, "warning"):
            logger.warning(msg)
        else:
            print(f"WARNING: {msg}")

    for obj in self._objects():
        num_objects += 1
        is_valid = True
        try:
            # Validate the object itself if requested.
            if validate_objects:
                # Prefer an explicit validate method if present.
                if hasattr(obj, "validate") and callable(obj.validate):
                    is_valid = obj.validate()
                # Fallback: if object has a 'schema' attribute, use it.
                elif hasattr(obj, "schema") and hasattr(obj, "data"):
                    from schema import Schema, SchemaError  # Imported lazily to avoid dependency at import time.
                    try:
                        Schema(obj.schema).validate(obj.data)
                    except SchemaError:
                        is_valid = False

            # Check digests if requested.
            if check_digests:
                # Expect the object to expose an expected_digest and compute_digest attributes.
                expected = getattr(obj, "expected_digest", None)
                compute = getattr(obj, "compute_digest", None)
                if expected is not None and callable(compute):
                    actual = compute()
                    if actual != expected:
                        is_valid = False
                else:
                    # If we can't compute a digest, skip this check but warn the user.
                    if show_warnings:
                        _log_warning(f"Digest check skipped for {obj} – missing expected_digest or compute_digest")

        except Exception as exc:
            # Any unexpected exception makes the object invalid.
            is_valid = False
            if show_warnings:
                _log_warning(f"Exception while validating {obj}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Input validation
    if not isinstance(validate_objects, bool):
        raise TypeError(f"validate_objects must be a bool, got {type(validate_objects).__name__}")
    if not isinstance(check_digests, bool):
        raise TypeError(f"check_digests must be a bool, got {type(check_digests).__name__}")
    if not isinstance(show_warnings, bool):
        raise TypeError(f"show_warnings must be a bool, got {type(show_warnings).__name__}")

    # Attempt to retrieve the collection of objects from the hierarchy.
    # This method is intentionally flexible: the hierarchy may expose its
    # objects via a ``objects`` attribute, a ``get_objects`` method, or a
    # ``root`` attribute containing an iterable of child objects.
    objects_iter = None
    if hasattr(self, "objects"):
        objects_iter = getattr(self, "objects")
    elif hasattr(self, "get_objects") and callable(getattr(self, "get_objects")):
        try:
            objects_iter = self.get_objects()
        except Exception:
            objects_iter = None
    elif hasattr(self, "root"):
        root = getattr(self, "root")
        if hasattr(root, "__iter__"):
            objects_iter = root
    if objects_iter is None:
        # If we cannot find any objects, we return zero counts.
        return (0, 0)

    num_objects = 0
    good_objects = 0

    # Iterate over the objects and perform validation checks.
    for obj in objects_iter:
        num_objects += 1
        obj_valid = True

        # Validate the object itself if requested.
        if validate_objects:
            try:
                # Prefer a 'validate' method; fall back to 'is_valid'.
                if hasattr(obj, "validate") and callable(getattr(obj, "validate")):
                    obj_valid = obj.validate()
                elif hasattr(obj, "is_valid") and callable(getattr(obj, "is_valid")):
                    obj_valid = obj.is_valid()
                else:
                    # No explicit validation method; assume valid.
                    obj_valid = True
            except Exception as exc:
                obj_valid = False
                if show_warnings:
                    print(f"Warning: Object {repr(obj)} raised an exception during validation: {exc}")

        # Check digests if requested.
        if obj_valid and check_digests:
            try:
                # If the object provides a 'compute_digest' method, compare to the stored 'digest'.
                has_compute = hasattr(obj, "compute_digest") and callable(getattr(obj, "compute_digest"))
                has_stored = hasattr(obj, "digest")
                if has_compute and has_stored:
                    computed = obj.compute_digest()
                    stored = getattr(obj, "digest")
                    if computed != stored:
                        obj_valid = False
                        if show_warnings:
                            print(f"Warning: Digest mismatch for object {repr(obj)}. "
                                  f"Stored: {stored}, Computed: {computed}")
                # If the object defines a 'digest' attribute but no compute method, we cannot verify.
                # If it defines a 'verify_digest' method, use that.
                elif hasattr(obj, "verify_digest") and callable(getattr(obj, "verify_digest")):
                    obj_valid = obj.verify_digest()
                else:
                    # No digest information; skip
                    pass
            except Exception as exc:
                obj_valid = False
                if show_warnings:
                    print(f"Warning: Object {repr(obj)} raised an exception during digest check: {exc}")

        if obj_valid:
            good_objects += 1
        else:
            if show_warnings:
                print(f"Warning: Validation failed for object {repr(obj)}")

    return (num_objects, good_objects)

