            return num_objects, good_objects

        # Normalize to iterable
        if isinstance(container, dict):
            objects = container.values()
        elif hasattr(container, '__iter__'):
            objects = container
        else:
            if show_warnings:
                print("Warning: 'storage_root' is not iterable.")
            return num_objects, good_objects

        for obj in objects:
            num_objects += 1
            is_ok = True
            if validate_objects:
                if not _is_valid(obj):
                    is_ok = False
                    if show_warnings:
                        print(f"Warning: Object {obj!r} failed validation.")
            if check_digests:
                if not _digest_ok(obj):
                    is_ok = False
                    if show_warnings:
                        print(f"Warning: Object {obj!r} failed digest check.")
            if is_ok:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Ensure parameters are booleans
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    # Attempt to get the iterable of objects in the hierarchy
    # Common patterns: a list attribute `objects`, or a getter method `get_objects()`
    try:
        if hasattr(self, 'objects'):
            objects = self.objects
            if not hasattr(objects, '__iter__'):
                raise TypeError("`objects` attribute is not iterable")
        elif hasattr(self, 'get_objects'):
            objects = self.get_objects()
            if not hasattr(objects, '__iter__'):
                raise TypeError("`get_objects()` did not return an iterable")
        else:
            # Fallback: no objects found
            objects = []
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve objects for hierarchy validation: {exc}")

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object itself
        if validate_objects:
            try:
                # Assume there is a method `validate_object` on this instance
                is_valid = getattr(self, 'validate_object', lambda o: True)(obj)
                if not is_valid:
                    if show_warnings:
                        print(f"Validation failed for object {getattr(obj, 'id', str(obj))}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Validation exception for object {getattr(obj, 'id', str(obj))}: {exc}")

        # Check digests if requested
        if is_valid and check_digests:
            try:
                # Expected digest from the object (attribute or method)
                expected_digest = getattr(obj, 'digest', None) or getattr(obj, 'get_digest', lambda: None)()
                # Actual digest computed by the hierarchy (method on self)
                actual_digest = getattr(self, 'compute_digest', lambda o: None)(obj)
                if expected_digest != actual_digest:
                    is_valid = False
                    if show_warnings:
                        print(f"Digest mismatch for object {getattr(obj, 'id', str(obj))}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Digest check exception for object {getattr(obj, 'id', str(obj))}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    # Determine the root directory to be initialized
    root = getattr(self, "root", None)
    if not root:
        raise ValueError("No storage root path specified.")

    try:
        # If the root already exists, ensure it looks like an OCFL root
        if os.path.exists(root):
            if not os.path.isdir(root):
                raise ValueError(f"Root path {root!r} exists but is not a directory.")
            ocfl_meta = os.path.join(root, ".ocfl_root")
            if os.path.exists(ocfl_meta):
                raise RuntimeError(f"OCFL storage at {root!r} appears already initialized.")
        else:
            # Create the root directory
            os.makedirs(root)

        # Create required subdirectories
        for subdir in ("objects", "commits"):
            dir_path = os.path.join(root, subdir)
            os.makedirs(dir_path, exist_ok=True)

        # Write a minimal OCFL root metadata file
        meta_file = os.path.join(root, ".ocfl_root")
        with open(meta_file, "w", encoding="utf-8") as fh:
            fh.write("OcflSpecVersion: 1.0\n")

    except OSError as exc:
        raise RuntimeError(f"Failed to initialize OCFL storage root {root!r}: {exc}") from exc

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Import locally to avoid module-level imports
    import os
    import json
    from pathlib import Path

    # Ensure the root path is set and valid
    if not hasattr(self, "root_path"):
        raise ValueError("The instance must have a 'root_path' attribute specifying the storage root.")
    root = Path(self.root_path).expanduser()
    if not root.is_absolute():
        root = root.resolve()
    if root.exists() and not root.is_dir():
        raise ValueError(f"Root path {root} exists but is not a directory.")

    # Create the root directory if it does not exist
    try:
        os.makedirs(root, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Failed to create OCFL root directory '{root}': {exc}") from exc

    # Create the OCFL descriptor file if it is missing
    descriptor_file = root / ".ocfl_root.json"
    if not descriptor_file.exists():
        try:
            # A minimal OCFL descriptor that satisfies most implementations
            minimal_descriptor = {
                "descriptor": {
                    "ocflRoot": {
                        "value": str(root),
                        "format": "application/json"
                    }
                }
            }
            descriptor_file.write_text(json.dumps(minimal_descriptor, indent=2), encoding="utf-8")
        except OSError as exc:
            raise RuntimeError(f"Could not write OCFL descriptor '{descriptor_file}': {exc}") from exc

    # Mark the instance as initialized
    self._initialized = True
    return None

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Determine the root directory path
    try:
        root_path = str(self.root_path)
    except AttributeError:
        raise ValueError("Missing required attribute 'root_path' for initialization.") from None

    # Ensure the root directory does not already exist or is empty
    if os.path.exists(root_path):
        if os.listdir(root_path):
            raise ValueError(f"Root directory '{root_path}' exists and is not empty.")
    else:
        try:
            os.makedirs(root_path, exist_ok=False)
        except OSError as exc:
            raise RuntimeError(f"Failed to create root directory '{root_path}': {exc}") from exc

    # Create the content layout file and compute its checksum
    layout_file = os.path.join(root_path, "content-layout")
    layout_bytes = b"v1"
    try:
        with open(layout_file, "wb") as f:
            f.write(layout_bytes)
    except OSError as exc:
        raise RuntimeError(f"Failed to write content layout file '{layout_file}': {exc}") from exc

    try:
        checksum = hashlib.sha256(layout_bytes).hexdigest()
    except Exception as exc:  # pragma: no cover
        checksum = None

    # Prepare the OCFL root manifest
    manifest_data = {
        "root": root_path,
        "content_layout": {"file": "content-layout", "checksum": checksum, "content": "v1"},
    }
    manifest_file = os.path.join(root_path, "root.manifest")
    try:
        with open(manifest_file, "w", encoding="utf-8") as f:
            json.dump(manifest_data, f, indent=2)
    except Exception as exc:
        raise RuntimeError(f"Failed to write root manifest file '{manifest_file}': {exc}") from exc

    return None

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    if not version:
        return ""

    try:
        import re
    except ImportError:
        return version

    # Find all contiguous digit groups
    digit_groups = list(re.finditer(r'\d+', version))
    if not digit_groups:
        return version

    last = digit_groups[-1]
    num_str = last.group()
    try:
        num = int(num_str)
    except ValueError:
        return version

    new_num = num + 1
    new_num_str = str(new_num)

    # Preserve leading zeros if present
    if len(num_str) > len(new_num_str) and num_str.lstrip('0'):
        new_num_str = new_num_str.zfill(len(num_str))

    start, end = last.span()
    new_version = version[:start] + new_num_str + version[end:]
    return new_version

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    parts = version.split('.')
    int_parts = []
    for p in parts:
        if not p.isdigit():
            return version
        int_parts.append(int(p))
    int_parts[-1] += 1
    new_parts = []
    for orig, val in zip(parts, int_parts):
        width = len(orig)
        s = str(val)
        if len(s) < width:
            s = s.zfill(width)
        new_parts.append(s)
    return '.'.join(new_parts)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # ensure there is at least one version directory
    if not version_dirs:
        return self  # nothing to validate

    # dictionary to record differences relative to the root inventory
    self.different_digests = {}

    root_inventory = None
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(
                f"Missing inventory file in version directory: {vdir}"
            )
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except Exception as e:
            raise ValueError(
                f"Failed to read inventory in {vdir}: {e}"
            ) from e

        if root_inventory is None:
            # the first inventory served as the root reference
            root_inventory = inventory
            continue

        # compare this inventory against the root inventory
        diff = {
            name: digest
            for name, digest in inventory.items()
            if root_inventory.get(name) != digest
        }
        if diff:
            self.different_digests.setdefault(vdir, {}).update(diff)

    # Optionally verify that each inventory contains all items present in the root
    for vdir in version_dirs[1:]:
        inv_path = os.path.join(vdir, "inventory.json")
        with open(inv_path, "r", encoding="utf-8") as fh:
            inventory = json.load(fh)
        missing = set(root_inventory.keys()) - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory in {vdir} is missing items: {', '.join(sorted(missing))}"
            )

    return self

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic input validation
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple")
        if not all(isinstance(d, str) for d in version_dirs):
            raise TypeError("All items in version_dirs must be string paths")

        # Store differences between inventories
        self.different_digests = {}

        # Keep a running union of inventories seen so far
        cumulative_inventory = {}
        root_inventory = None

        for idx, vd in enumerate(version_dirs):
            # Resolve inventory path: try .json first, then plain file
            inv_path = os.path.join(vd, 'inventory.json')
            if not os.path.exists(inv_path):
                inv_path = os.path.join(vd, 'inventory')
                if not os.path.exists(inv_path):
                    raise FileNotFoundError(f"No inventory file found in '{vd}'")

            # Load inventory
            try:
                with open(inv_path, 'r') as f:
                    inv_data = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to load inventory in '{vd}': {e}")

            # Ensure inventory is a mapping of filename -> digest
            if not isinstance(inv_data, dict):
                raise ValueError(f"Inventory in '{vd}' must be a mapping")

            # First inventory becomes the root inventory for comparison
            if idx == 0:
                root_inventory = inv_data
            else:
                # Verify that cumulative inventory up to previous version is a subset
                for fname, dgt in cumulative_inventory.items():
                    if fname not in inv_data:
                        raise ValueError(
                            f"Missing file '{fname}' in inventory of '{vd}', "
                            f"required from earlier versions"
                        )
                    if inv_data[fname] != dgt:
                        # Record difference
                        self.different_digests.setdefault(fname, []).append(
                            (vd, inv_data[fname], dgt)
                        )
                        raise ValueError(
                            f"Digest mismatch for '{fname}' in '{vd}'. "
                            f"Expected {dgt}, found {inv_data[fname]}"
                        )

            # Compare current inventory for any digests that differ from root inventory
            for fname, dgt in inv_data.items():
                if fname in root_inventory and root_inventory[fname] != dgt:
                    self.different_digests.setdefault(fname, []).append(
                        (vd, dgt, root_inventory[fname])
                    )

            # Update cumulative inventory
            cumulative_inventory.update(inv_data)

        return self

