    import json

    # Load the root inventory if it exists
    root_inventory = {}
    if hasattr(self, "root_inventory_path") and self.root_inventory_path and os.path.isfile(self.root_inventory_path):
        try:
            with open(self.root_inventory_path, "r", encoding="utf-8") as f:
                root_inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load root inventory from {self.root_inventory_path!r}: {exc}")

    # Prepare a place to store differences
    self.content_differences = {}

    base_dir = getattr(self, "base_dir", os.getcwd())

    for idx, dir_name in enumerate(version_dirs, start=1):
        version_path = os.path.join(base_dir, dir_name)
        inv_path = os.path.join(version_path, "inventory.json")

        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory file for version directory '{dir_name}': expected at {inv_path!r}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to read inventory from {inv_path!r}: {exc}")

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in {inv_path!r} is not a mapping object")

        # Each version should contain an inventory up to that point.
        # Verify that all entries present so far are in the inventory.
        missing = set(root_inventory.keys()) - set(inventory.keys())
        if missing:
            raise ValueError(
                f"Version directory '{dir_name}' inventory is missing entries: {sorted(missing)}"
            )

        # Record any digest differences from the root inventory
        for file_path, digest in inventory.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is None:
                # File not present in root; skip or record as possible addition
