def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*"
    Namaste files to determine the directory type.
    """
    import os

    # Helper to see if a directory contains a namaste file
    def has_namaste(dir_path):
        try:
            for name in os.listdir(dir_path):
                if name.startswith("0="):
                    return True
        except PermissionError:
            return False
        return False

    # If the path itself is a file
    if os.path.isfile(path):
        return "file"

    # If the path is not a directory either
    if not os.path.isdir(path):
        return f"unknown: path is not a file or directory ({path})"

    # Gather some hints
    dir_entries = set()
    try:
        dir_entries = set(os.listdir(path))
    except PermissionError:
        return "error: permission denied accessing directory"

    # Check for object boundaries
    has_object_json = "object.json" in dir_entries
    has_inventory_json = "inventory.json" in dir_entries
    # If we see object.json and inventory.json, we likely have an object folder
    if has_object_json and has_inventory_json:
        if has_namaste(path):
            return "object"
        else:
            return "error: object folder missing namaste file"

    # If no object.json/inventory.json but we do have a namaste file, could be storage root
    if has_namaste(path):
        # Check that the directory contains subdirectories (potential objects)
        subdirs = [d for d in dir_entries if os.path.isdir(os.path.join(path, d))]
        if subdirs:
            return "root"
        else:
            # No subdirectories - ambiguous, but we consider it a storageroot with no objects
            return "root"

    # No namaste file present: we can't determine
    return "error: no namaste file found in directory"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if not os.path.exists(path):
            return "path does not exist"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            try:
                entries = os.listdir(path)
            except OSError as exc:
                return f"error listing directory: {exc}"

            # If the directory itself contains a namaste file "0=*", consider it an object.
            for name in entries:
                if name.startswith("0="):
                    return "object"

            # If a directory contains any entries but no "0=*",
            # assume it is a storage root.
            if entries:
                return "root"

            # Empty directory: ambiguous, return descriptive error
            return "empty directory, no namaste file found"

        # Other types (e.g., symlink, special file) are outside scope
        return f"unknown filesystem object at {path}"
    except Exception as exc:
        return f"error: {exc}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate inputs
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")
    if bug_ids is None:
        return params

    # Normalise bug_ids to a list of strings
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    elif isinstance(bug_ids, (list, tuple)):
        bug_ids = list(bug_ids)
    else:
        raise ValueError("bug_ids must be a scalar, list, or tuple")

    # Convert all entries to string and strip whitespace
    bug_ids = [str(b).strip() for b in bug_ids if str(b).strip()]

    # Merge into existing 'ids' or create it
    if 'ids' in params:
        # Existing ids may be a string or iterable
        existing = params['ids']
        if isinstance(existing, str):
            existing_ids = [e.strip() for e in existing.split(',') if e.strip()]
        elif isinstance(existing, (list, tuple)):
            existing_ids = [str(e).strip() for e in existing if str(e).strip()]
        else:
            existing_ids = []

        # Combine without duplicates while preserving order
        combined_ids = existing_ids
        for b in bug_ids:
            if b not in combined_ids:
                combined_ids.append(b)

        params['ids'] = ','.join(combined_ids)
    else:
        params['ids'] = ','.join(bug_ids)

    return params

