                ns, unknown = parser.parse_known_args(unparsed_arguments)
            except Exception as exc:
                raise ValueError(f"Parser for subcommand '{name}' failed to parse arguments: {exc}") from exc
            parsed_dict[name] = ns
            unknown_sets.append(set(unknown))
        # Find arguments unknown to all parsers
        common_unknown = set.intersection(*unknown_sets) if unknown_sets else set()
        # Preserve original order for remaining arguments
        remaining = [arg for arg in unparsed_arguments if arg in common_unknown]
        return parsed_dict, remaining

