def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    try:
        from collections.abc import Mapping
    except ImportError:
        # For Python 2 fallback
        import collections
        Mapping = collections.Mapping

    if not isinstance(url_args, Mapping):
        raise TypeError("url_args must be a mapping")

    import re
    import urllib.parse

    pattern = re.compile(r'\{([a-zA-Z0-9_]+)\}')

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            if value is None:
                value_str = ''
            else:
                value_str = str(value)
            # Percent‑encode the value for safe URL traversal
            try:
                return urllib.parse.quote(value_str, safe='')
            except Exception:
                # Fallback: return the string without encoding
                return value_str
        # If the placeholder is missing in url_args, keep it unchanged
        return match.group(0)

    try:
        return pattern.sub(_repl, url)
    except Exception as e:
        # In case of unexpected errors, return the original URL as a safeguard
        return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not isinstance(url_args, (dict,)):
        raise TypeError('url_args must be a mapping')

    import re  # local import to avoid outer dependency

    # Pattern matches {key} or :key placeholders
    placeholder_pattern = re.compile(r'\{([^{}]+)\}|\:([A-Za-z0-9_]+)')

    # If there are no placeholders, return the original URL
    matches = list(placeholder_pattern.finditer(url))
    if not matches:
        return url

    # Replace placeholders with corresponding values from url_args,
    # processing from the end to avoid index shifting
    result = url
    for match in reversed(matches):
        key = match.group(1) or match.group(2)
        if key in url_args and url_args[key] is not None:
            result = (
                result[:match.start()] + str(url_args[key]) + result[match.end():]
            )
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    # Pattern matches {var} or :var
    pattern = r'{(\w+)}|:(\w+)'

    def _repl(match):
        key = match.group(1) or match.group(2)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    return re.sub(pattern, _repl, url)

