    if parser is None:
        raise TypeError("parser must not be None")
    try:
        actions = getattr(parser, '_actions', None)
    except Exception:
        raise ValueError("Provided object does not have '_actions' attribute; not a valid argparse.ArgumentParser")
    if actions is None:
        return ""
    flags = []
    for action in actions:
        option_strings = getattr(action, 'option_strings', None)
        if option_strings:
            flags.extend(option_strings)
    return " ".join(flags)

def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        seq = list(vertices)
    except TypeError:
        raise TypeError('vertices must be an iterable of points')
    n = len(seq)
    if n < 1:
        raise ValueError('vertices must contain at least one vertex')
    return [(seq[i - 1], seq[i], seq[(i + 1) % n]) for i in range(n)]

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list of single-character strings")
    if any(not isinstance(ch, str) or len(ch) != 1 for ch in alphabet):
        raise ValueError("all elements in alphabet must be single-character strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet size must be at least 2 to represent numbers")

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()
        result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        pad_char = alphabet[0]
        result = pad_char * (padding - len(result)) + result

    return result

