    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if register_value is None:
        raise ValueError("register_value must not be None")

    def _replace(d):
        if isinstance(d, dict):
            new_dict = {}
            for k, v in d.items():
                new_key = str(register_number) if k == register_value else k
                new_dict[new_key] = _replace(v) if isinstance(v, (dict, list)) else v
            return new_dict
        elif isinstance(d, list):
            return [_replace(item) if isinstance(item, (dict, list)) else item for item in d]
        else:
            return d

    return _replace(flow_params)

