def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type, got %r" % cls)
    seen = set()
    queue = [cls]
    while queue:
        parent = queue.pop()
        try:
            children = parent.__subclasses__()
        except Exception:
            continue
        for child in children:
            if child not in seen:
                seen.add(child)
                queue.append(child)
    seen.discard(cls)
    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class type, got %r" % (cls,))
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            current_subs = current.__subclasses__()
        except Exception:
            current_subs = []
        for sub in current_subs:
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    seen.discard(cls)
