        # Resolve the hostname or IP
        addr_infos = socket.getaddrinfo(cleaned_host, None, 0, 0, socket.IPPROTO_TCP)
    except socket.gaierror:
        # Name could not be resolved
        return False

    # Check each address family for a loopback address
    for family, _, _, _, sockaddr in addr_infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == '::1':
                return True

    return False

