def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, (str, bytes, bytearray)):
        raise TypeError("rendered_config must be a string or bytes")
    if not isinstance(mode, int) or not (0 <= mode <= 0o777):
        raise ValueError("mode must be an integer between 0 and 0o777 inclusive")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    config_path = os.path.expanduser(config_filename)

    # Abort if file exists and overwrite is False
    if not overwrite and os.path.isfile(config_path):
        return

    # Ensure parent directories exist
    parent_dir = os.path.dirname(config_path)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories for {config_path}") from exc

    # Determine write mode
    write_mode = 'wb' if isinstance(rendered_config, (bytes, bytearray)) else 'w'

    try:
        with open(config_path, write_mode) as fp:
            fp.write(rendered_config)
        # Set file permissions
        try:
            os.chmod(config_path, mode)
        except OSError as exc:
            # Permissions may not be set on some filesystems; log or ignore
            pass
    except OSError as exc:
        raise OSError(f"Failed to write configuration file {config_path}") from exc

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Retrieve the variable name from the matcher
    try:
        name = matcher.name
    except AttributeError:
        # Assume matcher is a regex match with a named group 'name'
        name = matcher.group('name')
    # Retrieve the default value if provided
    try:
        default = matcher.default
    except AttributeError:
        # If matcher is a regex match, attempt to get an optional 'default' group
        if 'default' in matcher.groupdict():
            default = matcher.group('default')
        else:
            default = None
    # Get the environment value, falling back to default if present
    value = os.environ.get(name, default)
    # If no value is found and no default was supplied, raise an error
    if value is None:
        raise KeyError(f'Environment variable {name!r} not found and no default provided')
    return value

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract name and default from the matcher
    if isinstance(matcher, (list, tuple)):
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        name = getattr(matcher, "name", None)
        if name is None:
            raise ValueError("Matcher must provide a 'name' (or be indexable)")
        default = getattr(matcher, "default", None)

    try:
        return os.environ[name]
    except KeyError:
        if default is not None:
            return default
        raise EnvironmentError(f'Environment variable "{name}" not found')

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")

    parsed = urllib.parse.urlparse(image_href)
    if not parsed.scheme or not parsed.netloc:
        raise ValueError("image_href must contain scheme and netloc")

    use_ssl = parsed.scheme.lower() == 'https'
    path = parsed.path
    if not path:
        raise ValueError("URL path missing")

    parts = [p for p in path.split('/') if p]
    if not parts:
        raise ValueError("URL path does not contain an image component")

    filename = parts[-1]
    # Remove any leading/trailing slashes are already removed by split
    if '.' in filename:
        image_id = filename.rsplit('.', 1)[0]
    else:
        image_id = filename

    return (image_id, parsed.netloc, use_ssl)

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern

    If pattern is a string, it will be compiled into a regular expression.
    Leading and trailing whitespace will be stripped if ``strip`` is True.
    If pattern is already a compiled regular expression, it is returned unchanged.
    Raises a TypeError for unsupported pattern types.
    """
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Determine the compiled regex type (Python 3.7+ or earlier)
    try:
        pattern_type = re.Pattern
    except AttributeError:
        pattern_type = type(re.compile(''))
    if isinstance(pattern, pattern_type):
        return pattern
    raise TypeError(f"Unsupported pattern type: {type(pattern).__name__}")

