def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # Return None if no pattern is provided
    if pattern is None:
        return None

    # Determine the type of compiled regex patterns
    try:
        compiled_type = type(re.compile(""))
    except Exception:
        compiled_type = None

    # If it's already a compiled regex pattern, just return it
    if compiled_type and isinstance(pattern, compiled_type):
        return pattern

    # If it's a string, optionally strip whitespace and compile it
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # If it has a .pattern attribute, attempt to compile that
    if hasattr(pattern, "pattern"):
        try:
            # Ensure we pass a string to re.compile
            return re.compile(str(pattern.pattern))
        except Exception:
            pass

    # If none of the above, raise a helpful error
    raise TypeError(f"Invalid pattern type: {type(pattern)!r}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        command = [commands]
    elif isinstance(commands, (list, tuple)):
        command = list(commands)
    else:
        raise TypeError(f"commands must be a string or a list/tuple of strings, got {type(commands).__name__}")

    if args:
        if not isinstance(args, (list, tuple)):
            raise TypeError(f"args must be a list or tuple of strings, got {type(args).__name__}")
        command.extend(args)

    if verbose:
        print(f"Running command: {' '.join(command)}")

    # Determine stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Execute the command
    try:
        result = subprocess.run(
            command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        msg = f"Command {' '.join(exc.cmd)} failed with exit code {exc.returncode}"
        if not hide_stderr and exc.stderr is not None:
            msg += f"\nStderr: {exc.stderr.strip()}"
        raise RuntimeError(msg) from exc

    return result.stdout.strip()

