def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import sys
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not isinstance(args, (list, tuple)):
        raise TypeError("'args' must be a list of argument lists")
    if len(commands) != len(args):
        raise ValueError("'commands' and 'args' must have the same length")
    outputs = []
    for cmd, cmd_args in zip(commands, args):
        if not isinstance(cmd_args, (list, tuple)):
            raise TypeError("Each entry in 'args' must be a list of arguments")
        full_cmd = [str(cmd)] + [str(a) for a in cmd_args]
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}", flush=True)
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=True
            )
            outputs.append(result.stdout)
            if not hide_stderr and result.stderr:
                if verbose:
                    print(result.stderr, file=sys.stderr, flush=True)
        except subprocess.CalledProcessError as exc:
            raise RuntimeError(f"Command '{' '.join(full_cmd)}' failed with exit code {exc.returncode}") from exc
    return outputs

