def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    else:
        roots = set(roots)

    # Verify that the graph object supports triples iteration
    if not hasattr(graph, "triples"):
        raise TypeError("graph must provide a 'triples' method for iterating triples")

    try:
        subjects = set()
        objects = set()
        for s, p, o in graph.triples((None, prop, None)):
            subjects.add(s)
            objects.add(o)

        # A root is a subject that never appears as a parent (object) in any triple
        for s in subjects:
            if s not in objects:
                roots.add(s)
    except Exception as e:
        raise RuntimeError(f"Failed to compute roots: {e}") from e

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if graph is None:
        return set()

    try:
        # Nodes that appear as subjects are children (have at least one parent)
        children = set(graph.subjects(predicate=prop))
        # Nodes that appear as objects are parents (potential roots)
        parents = set(graph.objects(predicate=prop))
    except Exception:
        # In case the graph or prop is not valid, return an empty set
        return set()

    # Roots are parents that are never children
    root_nodes = parents - children

    # If a specific set of nodes is provided, constrain the result to those
    if roots is not None:
        root_nodes = root_nodes & roots

    return root_nodes

