def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate the shape
    try:
        shape_tuple = tuple(shape)
    except Exception:
        raise TypeError("shape must be an iterable of integers")

    if not all(isinstance(s, (int, np.integer)) and s >= 0 for s in shape_tuple):
        raise ValueError("All shape dimensions must be non‑negative integers")

    # Validate and normalize the dtype
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception:
            raise TypeError("dtype must be a numpy.dtype or convertible to one")

    # Create and return the array
    try:
        return np.empty(shape_tuple, dtype=dtype)
    except Exception as e:
        raise ValueError(f"Could not create array with shape {shape_tuple} and dtype {dtype}: {e}")

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be array-like convertible to float") from e
    mu = 0.2
    sigma = 0.1
    coeff = 1.0/(sigma*np.sqrt(2*np.pi))
    return coeff * np.exp(-((x_arr - mu)**2) / (2 * sigma**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import toml
    except ImportError:
        toml = None
    try:
        import yaml
    except ImportError:
        yaml = None

    configs = {}
    errors = []

    def expand_env_on_strings(obj):
        if isinstance(obj, dict):
            return {k: expand_env_on_strings(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [expand_env_on_strings(v) for v in obj]
        if isinstance(obj, str) and resolve_env:
            return os.path.expandvars(obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to read configuration file {filename!r}: {exc}',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        ext = os.path.splitext(filename)[1].lower()
        parsed = None
        try:
            if ext == '.toml':
                if toml is None:
                    raise ImportError('toml library not installed')
                parsed = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError('yaml library not installed')
                parsed = yaml.safe_load(raw)
            elif ext == '.json':
                parsed = json.loads(raw)
            else:
                # Unsupported extension; treat as plain text
                parsed = raw
            if parsed is None:
                parsed = {}
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to parse configuration file {filename!r}: {exc}',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        # Apply overrides if provided
        if overrides:
            if isinstance(parsed, dict):
                try:
                    parsed.update(overrides)
                except Exception as exc:
                    record = logging.LogRecord(
                        name='load_configurations',
                        level=logging.ERROR,
                        pathname=filename,
                        lineno=0,
                        msg=f'Failed to apply overrides to configuration {filename!r}: {exc}',
                        args=(),
                        exc_info=None
                    )
                    errors.append(record)
        # Expand environment variables if requested
        try:
            parsed = expand_env_on_strings(parsed)
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to expand environment variables in {filename!r}: {exc}',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        configs[filename] = parsed

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import logging
    import json
    import re

    # Attempt to import optional parsers
    try:
        import toml  # type: ignore
    except Exception:
        toml = None
    try:
        import yaml  # type: ignore
    except Exception:
        yaml = None

    # Prepare result containers
    configs = {}
    error_records = []

    # Logger to capture errors
    logger = logging.getLogger("load_configurations")
    logger.setLevel(logging.ERROR)
    logger.handlers.clear()
    logger.propagate = False

    class ListHandler(logging.Handler):
        def emit(self, record):
            error_records.append(record)

    logger.addHandler(ListHandler())

    # Helper to resolve environment variables in a value
    env_pattern = re.compile(r"\$\{([^}]+)\}")

    def _resolve_env_in_value(v):
        if isinstance(v, str):
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return env_pattern.sub(repl, v)
        return v

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(_resolve_env_in_value(v)) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(_resolve_env_in_value(item)) for item in d]
        else:
            return _resolve_env_in_value(d)

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            contents = None
            with open(filename, "r", encoding="utf-8") as fp:
                contents = fp.read()

            ext = os.path.splitext(filename)[1].lower()
            parsed = None

            if ext == ".toml":
                if not toml:
                    raise ImportError("toml library not available")
                parsed = toml.loads(contents)
            elif ext in {".yaml", ".yml"}:
                if not yaml:
                    raise ImportError("yaml library not available")
                parsed = yaml.safe_load(contents)
            elif ext in {".json"}:
                parsed = json.loads(contents)
            else:
                # default to yaml
                if yaml:
                    parsed = yaml.safe_load(contents)
                else:
                    raise ValueError(f"Unsupported configuration file extension: {ext}")

            if overrides:
                if not isinstance(parsed, dict):
                    raise ValueError("Parsed configuration is not a dictionary; cannot apply overrides")
                parsed.update(overrides)

            if resolve_env:
                parsed = _resolve_env_in_dict(parsed)

            configs[filename] = parsed

        except Exception as exc:
            # Log the exception with a custom LogRecord
            message = f"Failed to load configuration from '{filename}': {exc}"
            logger.exception(message)

    return configs, error_records

