    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import toml
    import yaml
    from typing import Dict, List, Tuple

    configs: Dict[str, Dict] = {}
    error_records: List[logging.LogRecord] = []

    def resolve_env_vars(value):
        if isinstance(value, str):
            # Simple environment variable substitution ${VAR}
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def replacer(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return pattern.sub(replacer, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                raw = f.read()
            if filename.lower().endswith('.toml'):
                config = toml.loads(raw)
            elif filename.lower().endswith(('.yaml', '.yml')):
                config = yaml.safe_load(raw) or {}
            elif filename.lower().endswith('.json'):
                config = json.loads(raw)
            else:
                # Unsupported extension
                msg = f'Unsupported configuration file extension for {filename}'
                record = logging.LogRecord('config_loader', logging.ERROR,
                                           '', 0, msg, None, None)
                error_records.append(record)
                continue

            # Optional environment variable resolution
            if resolve_env:
                config = resolve_env_vars(config)

            # Apply overrides if provided
            if overrides and filename in overrides:
                if isinstance(overrides[filename], dict):
                    config.update(overrides[filename])

            # Simple validation: ensure config is a dict
            if not isinstance(config, dict):
                msg = f'Configuration in {filename} is not a dict'
                record = logging.LogRecord('config_loader', logging.ERROR,
                                           '', 0, msg, None, None)
                error_records.append(record)
                continue

            configs[filename] = config

        except FileNotFoundError as exc:
            msg = f'File not found: {filename}'
            record = logging.LogRecord('config_loader', logging.ERROR,
                                       '', 0, msg, None, None)
            error_records.append(record)
        except Exception as exc:
            msg = f'Failed to parse {filename}: {exc}'
            record = logging.LogRecord('config_loader', logging.ERROR,
                                       '', 0, msg, None, None)
            error_records.append(record)

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    error_records = []

    logger = logging.getLogger(__name__)

    for cfg_file in config_filenames:
        try:
            with open(cfg_file, 'r', encoding='utf-8') as f:
                raw = f.read()
            if cfg_file.endswith('.toml'):
                try:
                    import toml
                except ImportError:
                    raise RuntimeError("toml module not available for .toml files")
                cfg = toml.loads(raw)
            elif cfg_file.endswith(('.yaml', '.yml')):
                try:
                    import yaml
                except ImportError:
                    raise RuntimeError("yaml module not available for .yaml/.yml files")
                cfg = yaml.safe_load(raw)
            else:
                try:
                    import json
                except ImportError:
                    raise RuntimeError("json module not available for unknown file types")
                cfg = json.loads(raw)
            if overrides:
                if isinstance(cfg, dict):
                    cfg.update(overrides)
                else:
                    logger.warning("Overrides provided but configuration is not a dict for %s", cfg_file)
            if resolve_env:
                import os
                def resolve(obj):
                    if isinstance(obj, dict):
                        return {k: resolve(v) for k, v in obj.items()}
                    if isinstance(obj, list):
                        return [resolve(v) for v in obj]
                    if isinstance(obj, str):
                        return os.path.expandvars(obj)
                    return obj
                cfg = resolve(cfg)
            parsed_configs[cfg_file] = cfg
        except Exception as exc:
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                filename=cfg_file,
                lineno=0,
                msg=f"Error parsing configuration file {cfg_file}: {exc}",
                args=None,
                exc_info=None
            )
            error_records.append(record)
    return parsed_configs, error_records

