def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Ensure the scale attribute exists
    if not hasattr(self, "_scale"):
        self._scale = None

    def _compute_scale():
        """Compute the integral from the histogram data."""
        if not hasattr(self, "histogram"):
            raise AttributeError("Histogram data is missing.")
        try:
            # Sum over all entries, ignoring NaNs
            return float(np.nansum(self.histogram))
        except Exception as exc:
            raise RuntimeError(f"Failed to compute scale: {exc}") from exc

    # Recompute if requested or not yet computed
    if recompute or self._scale is None:
        self._scale = _compute_scale()

    # If other is not provided, just return the scale
    if other is None:
        return self._scale

    # Validate the provided scale target
    try:
        new_scale = float(other)
    except (TypeError, ValueError) as exc:
        raise TypeError(f"Provided scale must be a numeric value, got {type(other).__name__}") from exc

    # Can't rescale a histogram with zero integral
    if self._scale == 0.0:
        raise LenaValueError("Cannot rescale a histogram whose integral is zero.")

    # Compute scaling factor and apply to the histogram data
    factor = new_scale / self._scale
    try:
        self.histogram = np.asarray(self.histogram, dtype=float) * factor
    except Exception as exc:
        raise RuntimeError(f"Failed to rescale histogram: {exc}") from exc

    # Update the stored scale to the new value
    self._scale = new_scale
    return self

