                cand_params = list(cand_sig.parameters.values())

                # Ignore variable positional/keyword args for a looser comparison
                def normalize(params):
                    return [
                        p
                        for p in params
                        if p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
                    ]

                if len(normalize(iface_params)) != len(normalize(cand_params)):
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"{iface_sig} vs {cand_sig}"
                    )
            except Exception:
                # If signature cannot be inspected, skip check
                pass

