        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple verification errors: " + "; ".join(errors))
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # Step 1: interface provision check
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(
                f"{candidate!r} does not declare that it provides {iface!r}"
            )

    # Helper: determine method names defined in the interface
    iface_dict = iface.__dict__
    iface_methods = {
        name
        for name, value in iface_dict.items()
        if callable(value) and not name.startswith("_")
    }
    iface_attrs = {
        name
        for name, value in iface_dict.items()
        if not callable(value) and not name.startswith("_")
    }

    # Step 2: check methods exist and signatures match
    for name in iface_methods:
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} is missing required method {name!r}")
            continue
        interface_attr = getattr(iface, name)
        candidate_attr = getattr(candidate, name)
        try:
            iface_sig = inspect.signature(interface_attr)
            cand_sig = inspect.signature(candidate_attr)
            if iface_sig != cand_sig:
                errors.append(
                    f"Signature mismatch for method {name!r}: "
                    f"expected {iface_sig}, got {cand_sig}"
                )
        except Exception:
            # If we cannot inspect the signature, skip the check
            pass

    # Step 3: check required attributes exist
    for name in iface_attrs:
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} is missing required attribute {name!r}")

    # Final: raise exception if any errors were collected
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            # Join multiple errors into a single message
            raise Invalid("; ".join(errors))

    # All checks passed
    return True

