                    dt = datetime.datetime.fromisoformat(stripped)
                except Exception:
                    pass
                if dt:
                    if isinstance(tzinfo, int):
                        dt = dt.replace(tzinfo=_tz_from_offset(tzinfo))
                    elif hasattr(tzinfo, 'tzinfo'):
                        dt = dt.replace(tzinfo=tzinfo.tzinfo)
                    else:
