def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request."""
    # Defensive check for a None request
    if request is None:
        return False

    # Attempt to read the path. Django uses request.path, Flask uses request.path.
    path = getattr(request, "path", None)
    if path is None:
