        return text
    import re

    def link_attrs(url):
        """Return attribute string to add to a hyperlink."""
        return ' target="_blank" rel="noopener noreferrer"'

    url_pattern = re.compile(r'\b((?:https?://|www\.)[^\s<>"\'()]+)')

    def replace_link(match):
