def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    Returns True if verification succeeds, False otherwise.
    """
    import base64
    from cryptography.hazmat.primitives import serialization, hashes
    from cryptography.hazmat.primitives.asymmetric import padding
    from cryptography.exceptions import InvalidSignature
    import os

    if not (public_key and doc and signature):
        return False

    # Load the public key (PEM format)
    try:
        if isinstance(public_key, (bytes, bytearray)):
            key_data = public_key
        else:
            # Assume file path if string and file exists
            if os.path.isfile(public_key):
                with open(public_key, "rb") as f:
                    key_data = f.read()
            else:
                # Treat as PEM string
                key_data = public_key.encode()
        public_key_obj = serialization.load_pem_public_key(key_data)
    except Exception:
        return False

    # Decode the signature (expected to be base64)
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Canonicalize the XML document (simple UTF-8 bytes)
    # In real scenarios, proper XML canonicalization should be used.
    try:
        doc_bytes = doc.encode("utf-8")
    except Exception:
        return False

    # Verify the signature
    try:
        public_key_obj.verify(
            sig_bytes,
            doc_bytes,
            padding.PKCS1v15(),
            hashes.SHA256(),
        )
        return True
    except InvalidSignature:
        return False
    except Exception:
        return False

