                    href = link.get("href")
                    if template:
                        data["hcard_url"] = template.replace("{uri}", "")
                    elif href:
                        data["hcard_url"] = href
                    break
        return data
    except Exception:
        pass  # Not JSON, fall back to XRD

    # Parse XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    ns = {"xrd": "xri://$xrd*($v*2.0)"}
    subject = root.find("xrd:Subject", ns)
    aliases = root.findall("xrd:Alias", ns)

    result = {}
    if subject is not None and subject.text:
        result["subject"] = subject.text

    if aliases:
        result["aliases"] = [a.text for a in aliases if a.text]

    links = []
    for link in root.findall("xrd:Link", ns):
        rel = link.get("rel")
        href = link.get("href")
        template = link.get("template")
        link_dict = {}
        if rel:
            link_dict["rel"] = rel
        if href:
            link_dict["href"] = href
        if template:
            link_dict["template"] = template
        if link_dict:
            links.append(link_dict)
    if links:
        result["links"] = links

    # Attempt to derive an hcard_url
    hcard_url = None
    for link in links:
        rel = link.get("rel", "").lower()
        if "profile" in rel or "hcard" in rel:
            if "template" in link:
                hcard_url = link["template"].replace("{uri}", "")
            else:
                hcard_url = link.get("href")
            break
    if hcard_url:
        result["hcard_url"] = hcard_url

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        return json.loads(document)
    except Exception:
        # Assume XRD XML
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            # handle default namespace if present
            ns = {}
            if root.tag.startswith("{"):
                uri, _, _ = root.tag[1:].partition("}")
                ns["ns"] = uri
            else:
                ns["ns"] = ""
            def findtext(elem, path):
                if ns["ns"]:
                    return elem.find(f"ns:{path}", ns).text if elem.find(f"ns:{path}", ns) is not None else None
                else:
                    return elem.find(path).text if elem.find(path) is not None else None
            subject = findtext(root, "Subject")
            links = []
            for link in root.findall(".//ns:Link", ns) if ns["ns"] else root.findall(".//Link"):
                link_attrs = {k: v for k, v in link.attrib.items()}
                links.append(link_attrs)
            return {"subject": subject, "links": links}
        except Exception:
            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        # Normalise keys: use lowercase
        result = {}
        subject = data.get("subject") or data.get("Subject") or data.get("href")
        if subject:
            result["subject"] = subject
        # Handle public key
        pk = data.get("public_key") or data.get("PublicKey") or data.get("key")
        if pk:
            result["public_key"] = pk
        # Aliases
        aliases = data.get("aliases") or data.get("Alias") or []
        if isinstance(aliases, list):
            result["aliases"] = aliases
        elif isinstance(aliases, str):
            result["aliases"] = [aliases]
        # Links
        links = data.get("links") or data.get("Link") or []
        if isinstance(links, list):
            for link in links:
                rel = link.get("rel") or link.get("Rel") or ""
                href = link.get("href") or link.get("Href") or ""
                template = link.get("template") or link.get("Template") or ""
                if not rel:
                    continue
                rel = rel.lower()
                if "lrdd" in rel:
                    result["lrdd"] = {"template": template, "rel": rel, "href": href}
                if "hcard" in rel:
                    result["hcard_url"] = href
                if "pkey" in rel or "public_key" in rel:
                    result["public_key_url"] = href
        return result
    except Exception:
        # Not JSON, try XRD (XML)
        try:
            import xml.etree.ElementTree as ET
        except Exception:
            return None

        try:
            root = ET.fromstring(document)
        except Exception:
            return None

        ns = {"xrd": root.tag.split('}')[0].strip('{')} if "}" in root.tag else {}
        def find(tag):
            return root.find(tag, ns)

        result = {}
        subject = find("xrd:Subject")
        if subject is not None:
            result["subject"] = subject.text

        # Aliases
        aliases_el = root.findall("xrd:Alias", ns)
        if aliases_el:
            result["aliases"] = [el.text for el in aliases_el]

        # Links
        link_els = root.findall("xrd:Link", ns)
        for link in link_els:
            rel = link.get("rel", "").lower()
            href = link.get("href", "")
            template = link.get("template", "")
            if not rel:
                continue
            if "lrdd" in rel:
                result["lrdd"] = {"template": template, "rel": rel, "href": href}
            if "hcard" in rel:
                result["hcard_url"] = href
            if "pkey" in rel or "public_key" in rel:
                result["public_key_url"] = href

        return result if result else None
    except Exception:
        return None

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result: dict = {}
    if not document:
        return result

    # Try JSON format first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # Subject (acct:etc)
            if "subject" in data:
                result["subject"] = data["subject"]

            # Links may be present under "links" key
            links = data.get("links", [])
            if isinstance(links, list):
                for link in links:
                    if not isinstance(link, dict):
                        continue
                    rel = link.get("rel")
                    href = link.get("href")
                    template = link.get("template")
                    if rel and href:
                        result[rel] = href
                        if template:
                            result[f"{rel}_template"] = template
        return result
    except Exception:  # ValueError for JSON decode error, or other issues
        pass

    # If JSON parsing failed, try XRD (XML) format
    try:
        root = ElementTree.fromstring(document)
        # Subject attribute on root
        subject = root.attrib.get("subject")
        if subject:
            result["subject"] = subject

        # Find all <Link> tags
        for link in root.findall(".//Link"):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            template = link.attrib.get("template")
            if rel and href:
                result[rel] = href
                if template:
                    result[f"{rel}_template"] = template
        return result
    except Exception:
        # If parsing fails, return whatever was parsed (could be empty)
        return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try JSON first
        import json
        data = json.loads(document)
        subject = data.get("subject")
        links = data.get("links")
        if not subject or not isinstance(links, list):
            return None
        return {"subject": subject, "links": links}
    except Exception:
        # Fall back to XRD (XML) parsing
        try:
            from xml.etree import ElementTree as etree
            root = etree.fromstring(document.encode("utf-8"))
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_el = root.find("xrd:Subject", ns)
            subject = subject_el.text if subject_el is not None else None
            if not subject:
                return None
            links = []
            for link in root.findall("xrd:Link", ns):
                rel = link.attrib.get("rel")
                href = link.attrib.get("href")
                if rel and href:
                    links.append({"rel": rel, "href": href})
            return {"subject": subject, "links": links}
        except Exception:
            return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # split the handle into local part and host
        _, host = handle.rsplit("@", 1)
    except ValueError:
        # invalid handle format
        return None
    try:
        from urllib.parse import quote
        import urllib.request

        url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.getcode() != 200:
                return None
            return response.read().decode("utf-8", errors="replace")
    except Exception:
        return None

