def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Normalize settings_dirs to a list of directory paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif settings_dirs is None:
        dirs = []
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            dirs = [settings_dirs]

    # Determine file matching logic based on spec_option
    if isinstance(spec_option, (list, tuple)):
        def check_file(name):
            return any(name.endswith(ext) for ext in spec_option)
    else:
        def check_file(name):
            return name.endswith(spec_option) if spec_option else True

    matched_paths = []
    for directory in dirs:
        try:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if check_file(fname):
                    matched_paths.append(os.path.join(directory, fname))
        except OSError:
            continue

    # Return a sorted list of fully qualified filenames
    return sorted(matched_paths)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        import os
        import glob

        # Accept a single directory string or a list/tuple of directories
        if isinstance(settings_dirs, str):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)

        # Default to searching for .ini files if no spec_option is provided
        pattern = spec_option if spec_option else "*.ini"

        found_files = []
        for d in dirs:
            abs_dir = os.path.abspath(d)
            # Ensure the directory exists before attempting to list files
            if not os.path.isdir(abs_dir):
                continue
            found_files.extend(glob.glob(os.path.join(abs_dir, pattern)))

        # Return a sorted list of unique file paths
        return sorted(set(found_files))
    except Exception:
        # In case of any error (missing import, bad path, etc.), return an empty list
        return []

def list_of_file_names(settings_dirs, spec_option=None):
    """Create a new IniType complex type

    Returns a sorted list of fully qualified file names from the given
    ``settings_dirs`` that match ``spec_option``.  If ``spec_option`` is
    ``None`` then all files with the ``.ini`` extension are returned.
    Any errors accessing a directory result in an empty list being
    returned.
    """
    import os
    import fnmatch
    from collections import OrderedDict

    # Normalize the directory input to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            raise ValueError("settings_dirs must be a path string or iterable of paths")

    # Determine the matching pattern
    if spec_option is None:
        pattern = "*.ini"
    else:
        # Ensure string pattern; if a tuple/list provided take first element
        if isinstance(spec_option, (str, bytes)):
            pattern = spec_option
        else:
            try:
                pattern = list(spec_option)[0]
            except Exception as exc:
                raise ValueError("spec_option must be a string pattern or iterable of patterns") from exc

    matched_paths = OrderedDict()

    for directory in dirs:
        try:
            for fname in os.listdir(directory):
                if fnmatch.fnmatch(fname, pattern):
                    full_path = os.path.join(directory, fname)
                    matched_paths[full_path] = None
        except OSError:  # pragma: no cover
            continue

    return sorted(matched_paths.keys())

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Ensure settings_dirs is iterable
        if not isinstance(settings_dirs, (list, tuple)):
            settings_dirs = [settings_dirs]
        # Normalise the file extension
        ext = spec_option if spec_option.startswith('.') else '.' + spec_option
        file_paths = []
        for dir_path in settings_dirs:
            if not os.path.isdir(dir_path):
                continue
            for fname in os.listdir(dir_path):
                if fname.endswith(ext):
                    file_paths.append(os.path.join(dir_path, fname))
        return sorted(set(file_paths))
    except Exception:
        return []

