            args = args.strip().split()
        else:
            args = list(args)
    except Exception:
        # In case of unexpected input types, return an empty list
        return []

    # Define known silent option identifiers
    silent_set = {"q", "quiet", "silent", "s", "suppress", "no-output"}

    silent_args = []
    for arg in args:
        if not isinstance(arg, str):
            continue
        stripped = arg.lstrip("-").lower()
        if stripped in silent_set:
            silent_args.append(stripped)

    # Preserve the original order while removing duplicates
    seen = set()
    unique_silent = []
    for name in silent_args:
        if name not in seen:
            seen.add(name)
            unique_silent.append(name)

    return unique_silent

