def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.  ``args`` may be a ``dict`` mapping
        argument names to a dictionary of attributes, or a ``list`` of single
       ‑item dictionaries containing the same structure.

    This method verifies that whenever an argument specification includes a
    ``'length'`` key, the associated value (specified by the ``'value'`` key)
    does not exceed that length.  ``'length'`` must be an integral number.
    If a value is found to be too long, a :class:`ValueError` is raised.
    """
    def _check_one(arg_name, arg_attrs):
        # Skip if no length restriction or no value provided
        max_len = arg_attrs.get('length')
        if max_len is None:
            return
        if 'value' not in arg_attrs:
            return
        value = arg_attrs['value']

        # ``length`` must be an integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"length for argument {arg_name!r} must be an integer, "
                f"got {type(max_len).__name__}"
            )

        # Only enforce if the value has a length (str, list, tuple, dict, etc.)
        if hasattr(value, "__len__"):
            actual_len = len(value)
            if actual_len > max_len:
                raise ValueError(
                    f"argument {arg_name!r} length {actual_len} exceeds "
                    f"maximum allowed {max_len}"
                )

    if isinstance(args, dict):
        for name, attrs in args.items():
            _check_one(name, attrs)
    elif isinstance(args, list):
        for item in args:
            if not isinstance(item, dict) or len(item) != 1:
                raise ValueError(
                    "each item in a list of arguments must be a single‑item dict"
                )
            name, attrs = next(iter(item.items()))
            _check_one(name, attrs)
    else:
        raise TypeError("args must be a dict or a list of single‑item dicts")

