            raise TypeError(
                f"Argument {idx} is of type {type(item).__name__}; expected a 3‑tuple (value, min, max)")

        if len(item) != 3:
            raise TypeError(
                f"Argument {idx} must contain exactly three elements (value, min, max)")

        value, min_val, max_val = item

        # Validate that min and max are comparable and that min <= max
        try:
            if max_val < min_val:
                raise ValueError
        except Exception:
            raise ValueError(
                f"Argument {idx}: min ({min_val}) must not exceed max ({max_val})") from None

        # Check that the value falls within the inclusive range
        try:
            if not min_val <= value <= max_val:
                raise ValueError
        except Exception:
            raise ValueError(
                f"Argument {idx}: value {value} is outside the permitted range [{min_val}, {max_val}]") from None

    return arg_list

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: Either a mapping with keys ``value``, ``min``, ``max`` or a
                 three-element sequence (value, min, max).  All of ``min`` and
                 ``max`` must be numeric and ``value`` must lie in the closed
                 interval ``[min, max]``.  Raises :class:`ValueError` if the
                 value is out of bounds, or :class:`TypeError` if the input does
                 not conform to the expected format.
    """
    # Helper to perform the actual bounds check
    def _check_value(val, minimum, maximum):
        if not isinstance(val, (int, float, complex)):
            raise TypeError(f"value {val!r} must be numeric")
        if not isinstance(minimum, (int, float, complex)):
            raise TypeError(f"min {minimum!r} must be numeric")
        if not isinstance(maximum, (int, float, complex)):
            raise TypeError(f"max {maximum!r} must be numeric")
        if minimum > maximum:
            raise ValueError(f"min {minimum!r} cannot be greater than max {maximum!r}")
        if val < minimum or val > maximum:
            raise ValueError(
                f"value {val!r} is outside the allowed range [{minimum!r}, {maximum!r}]"
            )

    # Parse input which can be a mapping or a sequence
    if isinstance(args, dict):
        try:
            val = args["value"]
            mn = args["min"]
            mx = args["max"]
        except KeyError as exc:
            raise TypeError(f"Dictionary input must contain 'value', 'min', and 'max' keys") from exc
    elif isinstance(args, (list, tuple)) and len(args) == 3:
        val, mn, mx = args
    else:
        raise TypeError(
            "args must be a mapping with keys ('value', 'min', 'max') "
            "or a three-element sequence (value, min, max)"
        )

    _check_value(val, mn, mx)
    # If no exception was raised, validation succeeded; return the value for convenience
    return val

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Retrieve minimum and maximum bounds from the instance
        min_ = getattr(self, "min_", None)
        max_ = getattr(self, "max_", None)

        if min_ is None or max_ is None:
            raise AttributeError("Instance must provide 'min_' and 'max_' attributes for validation")

        # Ensure args is iterable; if not, put it in a tuple for uniform processing
        if not hasattr(args, "__iter__") or isinstance(args, (str, bytes)):
            args = (args,)

        for val in args:
            try:
                if val < min_ or val > max_:
                    raise ValueError(
                        f"Value {val!r} outside allowed range [{min_}, {max_}]"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Cannot compare value {val!r} with bounds {min_!r} and {max_!r}: {exc}"
                ) from exc

        return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: Iterable of argument values to validate.
    :raises AttributeError: If the instance does not define ``min_`` or ``max_``.
    :raises TypeError: If an element in ``args`` is not an int or float.
    :raises ValueError: If any element is outside the defined bounds.
    """
    # Ensure the instance has min_ and max_ attributes
    if not hasattr(self, 'min_') or not hasattr(self, 'max_'):
        raise AttributeError("Instance must have 'min_' and 'max_' attributes for validation")

    min_val = self.min_
    max_val = self.max_

    # If there is no bound specified, skip validation
    if min_val is None and max_val is None:
        return args

    # Iterate over provided arguments, validate each
    for i, val in enumerate(args):
        if val is None:
            continue  # allow None values
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument at position {i} is not a numeric type: {val!r}")
        if min_val is not None and val < min_val:
            raise ValueError(f"Argument at position {i} ({val}) is less than minimum allowed ({min_val})")
        if max_val is not None and val > max_val:
            raise ValueError(f"Argument at position {i} ({val}) is greater than maximum allowed ({max_val})")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # If a mapping with a fully‑qualified type is supplied, delegate to the
    # existing `construct` helper which knows how to instantiate the object.
    if isinstance(spec_option, dict) and "__type__" in spec_option:
        try:
            return self.construct(spec_option)
        except Exception as exc:
            raise ValueError(
                f"Unable to construct complex type '{type_name}' for "
                f"option '{option_name}': {exc}"
            ) from exc

    # If `spec_option` is already a callable factory, call it with the option name
    if callable(spec_option):
        try:
            return spec_option(option_name=option_name, subcommand=subcommand)
        except Exception as exc:
            raise ValueError(
                f"Error while calling factory for complex type '{type_name}' "
                f"of option '{option_name}': {exc}"
            ) from exc

    # If `spec_option` is a string, treat it as a key into the subcommand's
    # registry of complex types, if one exists.
    if isinstance(spec_option, str):
        registry = getattr(subcommand, "complex_type_registry", {})
        factory = registry.get(spec_option)
        if factory is None:
            raise KeyError(
                f"Complex type '{spec_option}' is not registered for subcommand "
                f"'{subcommand!r}' when resolving option '{option_name}'."
            )
        try:
            return factory()
        except Exception as exc:
            raise ValueError(
                f"Error constructing complex type '{spec_option}' for option "
                f"'{option_name}': {exc}"
            ) from exc

    # As a last resort, return the value wrapped in a list to keep a
    # consistent return type for callers expecting an iterable of types.
    return [spec_option]

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non‑empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non‑empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non‑empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")

    # Resolve the type class
    type_cls = None
    if hasattr(self, "complex_type_registry"):
        type_cls = self.complex_type_registry.get(type_name)
    if type_cls is None:
        type_cls = globals().get(type_name)

    # If still unresolved, default to a simple factory that returns the kwargs
    if type_cls is None:
        def _fallback_factory(**kwargs):
            return kwargs
        type_cls = _fallback_factory

    # Extract constructor arguments
    args = spec_option.copy()
    constructor_args = args.pop("__args__", [])
    constructor_kwargs = dict(args)
    constructor_kwargs.update(
        {"subcommand": subcommand, "option_name": option_name}
    )

    try:
        instance = type_cls(*constructor_args, **constructor_kwargs)
    except Exception as exc:
        raise RuntimeError(
            f"Unable to instantiate complex type '{type_name}' for option "
            f"'{option_name}' with spec {spec_option}: {exc}"
        ) from exc

    return instance

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if spec_option is None:
        raise ValueError(f"spec_option for option '{option_name}' cannot be None")

    if not isinstance(spec_option, dict):
        raise TypeError(
            f"spec_option for option '{option_name}' must be a dict, got {type(spec_option)!r}"
        )

    # The expected key that specifies the fully qualified name of the type
    if "__type__" not in spec_option:
        raise KeyError(
            f"Missing '__type__' in spec_option for option '{option_name}'"
        )
    type_fqdn = spec_option.pop("__type__")

    # Prepare a function to load the type, preferring a classmethod if present
    load_type = getattr(self, "load_name", None)
    if load_type is None:
        # Fallback: use importlib to load the type
        def load_type(path):
            import importlib
            mod_path, _, cls_name = path.rpartition(".")
            if not mod_path:
                raise ImportError(f"Invalid type path '{path}'")
            module = importlib.import_module(mod_path)
            return getattr(module, cls_name)

    try:
        factory = load_type(type_fqdn)
    except Exception as exc:
        raise ImportError(
            f"Failed to load type '{type_fqdn}' for option '{option_name}': {exc}"
        ) from exc

    # Extract positional and keyword arguments for the constructor
    args = spec_option.pop("__args__", [])
    kwargs = spec_option.pop("__kwargs__", {})
    if not isinstance(args, (list, tuple)):
        raise TypeError(
            f"'__args__' for option '{option_name}' must be a list or tuple, got {type(args)!r}"
        )
    if not isinstance(kwargs, dict):
        raise TypeError(
            f"'__kwargs__' for option '{option_name}' must be a dict, got {type(kwargs)!r}"
        )

    # Any remaining items in spec_option are treated as keyword arguments
    kwargs.update(spec_option)

    try:
        instance = factory(*args, **kwargs)
    except Exception as exc:
        raise TypeError(
            f"Error constructing instance of '{type_fqdn}' for option '{option_name}': {exc}"
        ) from exc

    return instance

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        if args is None:
            return control_args, nested_args

        try:
            # Accept either a dict or an iterable of (key, value) pairs
            if hasattr(args, 'items'):
                iterator = args.items()
            else:
                iterator = args

            for key, value in iterator:
                if isinstance(key, str) and key.startswith("control_"):
                    # Strip prefix and add to control args
                    control_args[key[len("control_"):]] = value
                elif isinstance(key, str) and key.startswith("custom_"):
                    # Strip prefix and add to nested args
                    nested_args[key[len("custom_"):]] = value
                else:
                    nested_args[key] = value
        except Exception as exc:
            # Re-raise with context for debugging
            raise ValueError(f"Error processing arguments: {exc}") from exc

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalize input to a dictionary
    if args is None:
        return {}, {}
    if isinstance(args, dict):
        arg_dict = args
    elif isinstance(args, list):
        try:
            arg_dict = dict(args)
        except Exception as exc:
            raise ValueError('args must be a dict or a list of key-value pairs') from exc
    else:
        raise TypeError('args must be a dict or a list of key-value pairs')

    # Define control argument keys (common Molecule control options)
    control_keys = {
        'destroy', 'list', 'matrix', 'create', 'state',
        'verify', 'check-mode', 'prune', 'parallel', 'keep',
        'limit', 'profile', 'verbose', 'dry-run', 'check', 'force',
    }

    # Separate control and nested arguments
    control_args = {}
    nested_args = {}
    for key, value in arg_dict.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Ensure vars_dict is a dictionary; if None, treat as empty dict
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary or None")

    # If no extra_vars provided, simply return the existing dictionary
    if not extra_vars:
        return vars_dict

    # Validate that extra_vars is a list
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list of dictionaries or None")

    # Merge each dictionary in the extra_vars list into vars_dict
    for extra in extra_vars:
        if not isinstance(extra, dict):
            raise TypeError("each element of extra_vars must be a dictionary")
        vars_dict.update(extra)

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    # Normalize to a list
    if not isinstance(extra_vars, (list, tuple)):
        extra_vars = [extra_vars]
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str):
            if '=' in item:
                key, value = item.split('=', 1)
                vars_dict[key] = value
            else:
                # If the string has no '=' treat it as a key with empty string value
                vars_dict[item] = ''
        else:
            raise ValueError("Each extra_var must be a dict or a string in 'key=value' format")
    return vars_dict"

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``.

    The function accepts a dictionary ``vars_dict`` and a sequence
    ``extra_vars`` that contains dictionaries (or nested sequences of
    dictionaries). Each dictionary inside ``extra_vars`` is merged into
    ``vars_dict`` and overrides existing keys. The updated dictionary is
    returned and the original dictionary is modified in place.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List or sequence of dictionaries (or nested
                       sequences of dictionaries) containing the extra
                       variables
    :return: The merged dictionary ``vars_dict``

    Examples
    --------
    >>> d = {'x': 1, 'y': 2}
    >>> ex = [{'y': 3}, {'z': 4}]
    >>> merge_extra_vars(d, ex)
    {'x': 1, 'y': 3, 'z': 4}
    """
    # Validate input dictionary
    if isinstance(vars_dict, dict):
        target = vars_dict
    else:
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    # Nothing to merge
    if not extra_vars:
        return target

    # Normalize extra_vars to an iterable
    try:
        iterator = iter(extra_vars)
    except TypeError:
        raise TypeError(f"extra_vars must be an iterable of dicts, got {type(extra_vars).__name__}")

    for item in iterator:
        # If item is a dict, merge directly
        if isinstance(item, dict):
            target.update(item)
        # If item is a nested iterable (e.g., list or tuple) of dicts, flatten and merge
        elif isinstance(item, (list, tuple)):
            for sub in item:
                if isinstance(sub, dict):
                    target.update(sub)
        else:
            # Unsupported type inside extra_vars; silently ignore to keep behavior flexible
            continue

    return target

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
    if extra_vars is None:
        return vars_dict

    # If a single dict is supplied, treat it as a simple mapping
    if isinstance(extra_vars, dict):
        source_iterables = [extra_vars]
    else:
        # Expect an iterable of mappings
        try:
            source_iterables = list(extra_vars)
        except TypeError:
            raise TypeError(f"extra_vars must be a dict or an iterable of dicts, got {type(extra_vars).__name__}")

    for src in source_iterables:
        if not isinstance(src, dict):
            raise TypeError(f"Each item in extra_vars must be a dict, got {type(src).__name__}")
        for key, value in src.items():
            vars_dict[key] = value

    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``.

    The function accepts :param vars_dict: a dictionary that will be updated in place.
    :param extra_vars: a collection of key/value pairs. It can be a dictionary,
    a list/tuple of dictionaries, a list/tuple of ``(key, value)`` tuples, or
    a list/tuple of strings in the form ``'key=value'``. Also a single item
    of any of these types is accepted.

    Missing ``extra_vars`` leaves ``vars_dict`` unchanged. The updated
    dictionary is returned.

    Raises
    ------
    TypeError
        If ``vars_dict`` is not a dictionary or if an item in ``extra_vars``
        has an unsupported type.
    ValueError
        If a string item does not contain ``=`` or a tuple does not have
        exactly two elements.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict

    def _apply(item):
        # Handle individual items
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, (list, tuple)):
            if len(item) == 2:
                key, value = item
                vars_dict[key] = value
            else:
                raise ValueError("Tuple/list items must have exactly two elements")
        elif isinstance(item, str):
            if "=" not in item:
                raise ValueError("String items must be in 'key=value' format")
            key, value = item.split("=", 1)
            vars_dict[key] = value
        else:
            raise TypeError(f"Unsupported type for extra_vars item: {type(item).__name__}")

    # Single dict or dict-like
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    # Iterable of items
    elif isinstance(extra_vars, (list, tuple)):
        for sub_item in extra_vars:
            _apply(sub_item)
    else:
        # single non-iterable item
        _apply(extra_vars)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build base command
    command = ["ansible-playbook"]

    # Verbosity
    if verbose:
        if isinstance(verbose, int):
            command.append("-" + "v" * verbose)
        else:
            command.append(f"-{verbose}")

    # Additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f"--{key}")
            elif value is None:
                command.append(f"--{key}")
            else:
                command.extend([f"--{key}", str(value)])

    # Extra vars
    if extra_vars:
        command.append("--extra-vars")
        command.append(" ".join([f"{k}={v}" for k, v in extra_vars.items()]))

    # Append playbook path
    command.append(playbook_path)

    _debug("Executing Ansible call: %s", " ".join(command))
    try:
        p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = p.communicate()
        if p.returncode != 0:
            raise RuntimeError(f"ansible-playbook reported an error: {stderr.strip()}")
        return stdout
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

