     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess

    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    # Base command
    command = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, bool):
            # true = one level, false = no flag
            if verbose:
                command.append("-v")
        elif isinstance(verbose, int):
            if verbose > 0:
                command.append("-" + "v" * verbose)
        else:
            # assume string already formatted
            command.append(str(verbose))

    # Extra ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if value is None or value is True:
                # flag style
                command.append(f"--{key}")
            elif isinstance(value, bool) and not value:
                # false boolean: skip
                continue
            else:
                # For list values join with commas
                if isinstance(value, (list, tuple)):
                    val_str = ",".join(str(v) for v in value)
                else:
                    val_str = str(value)
                command.append(f"--{key}={val_str}")

    # Extra Vars
    if extra_vars:
        # Create a space separated key=value string
        ev_pairs = []
        for k, v in extra_vars.items():
            if v is None:
                continue
            ev_pairs.append(f"{k}={v}")
        ev_str = " ".join(ev_pairs)
        command

