    # Resolve playbook path relative to workspace if not absolute
    if not os.path.isabs(playbook_path):
        base = getattr(ir_workspace, "path", None) or getattr(ir_workspace, "root", None) or ""
        playbook_path = os.path.join(base, playbook_path)
    command.append(playbook_path)

    # Logging
    logger = getattr(ir_plugin, "log", None) or logging.getLogger(__name__)
    logger.debug("Executing ansible-playbook command: %s", " ".join(command))

    try:
        result = subprocess.run(command, capture_output=True, text=True, check=False)
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook command: {exc}") from exc

    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible reported an error ({result.returncode}): {result.stderr}"
        )

    return result.stdout.replace("\n", "") if result.stdout else result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Guard against invalid input
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict")

    # Retrieve the option definitions for the given parser
    try:
        options = self[parser_name]
    except TypeError:
        # self might not be subscriptable; treat as empty
        options = []
    except KeyError:
        # No parser with that name; nothing to convert
        return

    for opt in options:
        name = getattr(opt, "name", None)
        if name is None:
            continue

        if name not in values_dict:
            continue

        raw_value = values_dict[name]
        # Attempt to convert the raw string to the expected type
        try:
            if hasattr(opt, "convert") and callable(opt.convert):
                converted = opt.convert(raw_value)
            elif hasattr(opt, "type"):
                # opt.type may be a callable (e.g., int, float, bool)
                converted = opt.type(raw_value)
            else:
                # No conversion information; keep as is
                converted = raw_value
        except Exception:
            # If conversion fails, retain the original value
            converted = raw_value

        values_dict[name] = converted

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments (modified in place)
        """
        # Optional custom converters for specific parsers if defined on the instance
        custom_converters = getattr(self, "_parser_converters", {})
        parser_custom = custom_converters.get(parser_name, {})

        for key, value in list(values_dict.items()):
            # Skip non-string values that are already typed
            if isinstance(value, str):
                # Apply a custom converter if available
                if key in parser_custom:
                    try:
                        values_dict[key] = parser_custom[key](value)
                        continue
                    except Exception:
                        # If custom conversion fails, fall back to auto conversion
                        pass
                # Auto-detect common types: bool, int, float
                val_trim = value.strip()
                lower_val = val_trim.lower()
                if lower_val in {"true", "false", "1", "0", "yes", "no"}:
                    values_dict[key] = lower_val in {"true", "1", "yes"}
                else:
                    try:
                        values_dict[key] = int(val_trim)
                    except ValueError:
                        try:
                            values_dict[key] = float(val_trim)
                        except ValueError:
                            # keep original string if no conversion applies
                            pass
        # No explicit return; values_dict is modified in place.

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        # Unexpected type; return empty dict to avoid crashes
        return {}

    def _cast_value(val):
        # Preserve None values directly
        if val is None:
            return None
        # Try boolean conversion
        if isinstance(val, str):
            low = val.strip().lower()
            if low in ('true', 'false'):
                return low == 'true'
            # Try integer conversion
            try:
                if low.startswith(('0x', '0X')):
                    return int(low, 16)
                return int(low)
            except ValueError:
                pass
            # Try float conversion
            try:
                return float(low)
            except ValueError:
                pass
        # Return the original value if no conversion applies
        return val

    try:
        for key in list(values_dict.keys()):
            values_dict[key] = _cast_value(values_dict[key])
    except Exception:
        # In case of unexpected error, leave values_dict unchanged
        pass

    # parser_name is not used in this conversion logic but kept for compatibility
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    """
    # Attempt to get an explicit type map for the given parser
    type_map = getattr(self, "_parser_type_map", {}).get(parser_name, {})

    for key, raw_val in list(values_dict.items()):
        if raw_val is None:
            continue

        # Determine target type either from explicit mapping or by deduction
        target_type = type_map.get(key)

        # Helper function to convert using a type
        def cast(val, t):
            try:
                return t(val)
            except Exception:
                return val

        # If a target type is known, use it
        if target_type is not None:
            # Handle booleans specially
            if target_type is bool:
                if isinstance(raw_val, str):
                    low = raw_val.strip().lower()
                    if low in ("true", "1"):
                        values_dict[key] = True
                    elif low in ("false", "0"):
                        values_dict[key] = False
                    else:
                        values_dict[key] = cast(raw_val, bool)
                else:
                    values_dict[key] = bool(raw_val)
            elif target_type in (list, tuple):
                # If the value is a string, attempt to parse as a comma‑separated list
                if isinstance(raw_val, str):
                    try:
                        elements = [e.strip() for e in raw_val.split(",") if e.strip()]
                        values_dict[key] = target_type(elements)
                    except Exception:
                        values_dict[key] = cast(raw_val, target_type)
                else:
                    values_dict[key] = cast(raw_val, target_type)
            else:
                values_dict[key] = cast(raw_val, target_type)
            continue

        # No explicit type: try to infer from the string representation
        # Try integer
        try:
            int_val = int(raw_val)
            values_dict[key] = int_val
            continue
        except Exception:
            pass

        # Try float
        try:
            float_val = float(raw_val)
            # Avoid treating integers as floats – keep integer if no decimal part
            if "." not in str(raw_val) and "e" not in str(raw_val).lower():
                values_dict[key] = int(float_val)
            else:
                values_dict[key] = float_val
            continue
        except Exception:
            pass

        # Try boolean
        if isinstance(raw_val, str):
            low = raw_val.strip().lower()
            if low in ("true", "1"):
                values_dict[key] = True
                continue
            if low in ("false", "0"):
                values_dict[key] = False
                continue

        # Try comma‑separated list
        if isinstance(raw_val, str) and "," in raw_val:
            values_dict[key] = [e.strip() for e in raw_val.split(",") if e.strip()]
            continue

        # Try to evaluate a Python literal (e.g., for lists, dicts)
        try:
            import ast  # Imported lazily to avoid top‑level import
            evaluated = ast.literal_eval(raw_val)
            values_dict[key] = evaluated
        except Exception:
            # Leave the value as a string if nothing else matches
            pass

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    If an argument has a specified type in the parser definition, the value
    will be converted using that type or a custom conversion function.
    Unsupported or failing conversions leave the original string value intact.
    """
    # Retrieve the argument type mapping for the specified parser.
    # It is assumed that `self._parsers` is a dictionary of the form
    # {parser_name: {arg_name: type_or_callable, ...}, ...}
    parser_defs = getattr(self, "_parsers", {}).get(parser_name, {})
    if not parser_defs:
        # No known definitions for this parser; nothing to convert.
        return values_dict

    # Work on a copy of the dictionary keys to avoid runtime changes.
    for key in list(values_dict.keys()):
        if key not in parser_defs:
            continue  # No conversion rule for this key.

        raw_val = values_dict[key]
        conv = parser_defs[key]

        # Define a helper to perform the conversion with a fallback.
        def safe_convert(value, convert_fn):
            try:
                # Special handling for bool, converting common string forms.
                if convert_fn is bool:
                    if isinstance(value, str):
                        return value.strip().lower() in ("true", "1", "yes", "on")
                    return bool(value)
                # Convert using the provided callable (type or custom).
                return convert_fn(value)
            except Exception:
                # On any failure, keep the original value.
                return value

        # If the value is a list, convert each element individually.
        if isinstance(raw_val, list):
            new_val = [safe_convert(v, conv) for v in raw_val]
        else:
            new_val = safe_convert(raw_val, conv)

        values_dict[key] = new_val

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # try importing yaml; fall back if not available
    try:
        import yaml
    except Exception:  # pragma: no cover
        yaml = None

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' not found or is not a directory.")

    # Determine spec file (prefer json, fallback to yaml)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.exists(candidate):
            spec_path = candidate
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of "
                                f"'plugin.json', 'plugin.yaml', or 'plugin.yml'.")

    # Load spec content
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            try:
                spec_data = json.load(f)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Failed to parse JSON spec at '{spec_path}': {exc}") from exc
        else:
            if yaml is None:
                raise ImportError("PyYAML is required to parse YAML plugin specs.")
            try:
                spec_data = yaml.safe_load(f)
            except yaml.YAMLError as exc:
                raise ValueError(f"Failed to parse YAML spec at '{spec_path}': {exc}") from exc

    if not isinstance(spec_data, dict):
        raise TypeError(f"The plugin spec at '{spec_path}' must be a mapping/dictionary.")

    # Flatten helper
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(spec_data)

