        plugin_path / "plugin.yml",
        plugin_path / "spec.yaml",
        plugin_path / "spec.yml",
    ]

    spec_file = None
    for f in candidate_files:
        if f.is_file():
            spec_file = f
            break

    if spec_file is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. "
            "Supported files: plugin.json, spec.json, plugin.yaml, spec.yaml, plugin.yml, spec.yml."
        )

    # Load the spec content
    if spec_file.suffix.lower() in {".json"}:
        with spec_file.open("r", encoding="utf-8") as fh:
            spec_data = json.load(fh)
    else:
        # Try YAML
        try:
            import yaml
        except Exception as exc:
            raise RuntimeError(
                f"YAML parser not available: {exc}"
            ) from exc
        with spec_file.open("r", encoding="utf-8") as fh:
            spec_data = yaml.safe_load(fh)

    if not isinstance(spec_data, dict):
        raise ValueError(
            f"Spec file {spec_file} does not contain a top-level dictionary."
        )

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec_data)

