def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    # Attempt to import yaml if available
    try:
        import yaml  # type: ignore
    except Exception:
        yaml = None

    # Validate plugin_dir
    if not isinstance(plugin_dir, (str, os.PathLike)):
        raise TypeError(f"plugin_dir must be a path string or PathLike object, got {type(plugin_dir)}")
    path = os.fspath(plugin_dir)

    if not os.path.isdir(path):
        raise ValueError(f"Provided plugin_dir '{path}' is not a directory or does not exist")

    # Search for specification file
    spec_files = []
    for ext in ('.yaml', '.yml', '.json'):
        spec_files.append(os.path.join(path, f"spec{ext}"))
        spec_files.append(os.path.join(path, f"plugin{ext}"))

    spec_path = None
    for file in spec_files:
        if os.path.isfile(file):
            spec_path = file
            break

    if spec_path is None:
        # No spec file found
        return {}

    # Load the specification
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith(('.yaml', '.yml')):
                if yaml is None:
                    raise RuntimeError("PyYAML is required to parse YAML plugin specifications.")
                data = yaml.safe_load(f)
            elif spec_path.endswith('.json'):
                data = json.load(f)
            else:
                raise ValueError(f"Unsupported specification format: {spec_path}")
    except FileNotFoundError:
        # Should not happen because we checked existence, but handle gracefully
        return {}
    except (json.JSONDecodeError, yaml.YAMLError) as exc:
        raise ValueError(f"Failed to parse plugin spec file '{spec_path}': {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error while reading spec file '{spec_path}': {exc}") from exc

    if not isinstance(data, dict):
        # Unexpected top-level type
        return {}

    # Helper to flatten a nested dictionary
    def _flatten(current, parent_key=''):
        items = {}
        for key, value in current.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten(value, new_key))
            elif isinstance(value, list):
                for idx, item in enumerate(value):
                    list_key = f"{new_key}.{idx}"
                    if isinstance(item, dict):
                        items.update(_flatten(item, list_key))
                    else:
                        items[list_key] = item
            else:
                items[new_key] = value
        return items

    flat_dict = _flatten(data)
    return flat_dict

