    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten a nested dictionary.
    def _flatten_dict(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten_dict(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Locate the spec file. Prefer spec.json, then plugin.json.
    spec_files = ['spec.json', 'plugin.json']
    spec_path = None
    for fname in spec_files:
        potential_path = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential_path):
            spec_path = potential_path
            break

    if not spec_path:
        raise FileNotFoundError(
            f"No plugin spec JSON file found in '{plugin_dir}'. "
            f"Expected one of: {', '.join(spec_files)}"
