        raise RuntimeError(f'Failed to add spec option to CLI: {exc}') from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("root must be a non-empty path")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    abs_path = os.path.abspath(norm_path)
    abs_root = os.path.abspath(norm_root)
    try:
        rel_path = os.path.relpath(abs_path, abs_root)
    except ValueError:
        raise ValueError("Root '{0}' is not a prefix of path '{1}'".format(root, path))
    if rel_path == os.curdir:
        return ''
    return rel_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os

    # Normalize absolute paths
    path_abs = os.path.abspath(path)
    root_abs = os.path.abspath(root)

    # On Windows, ensure same drive
    if os.name == "nt":
        path_drive, _ = os.path.splitdrive(path_abs)
        root_drive, _ = os.path.splitdrive(root_abs)
        if path_drive.lower() != root_drive.lower():
            raise ValueError(
                f"Path '{path}' and root '{root}' are on different drives."
            )

    # Attempt to compute relative path
    try:
        relative = os.path.relpath(path_abs, root_abs)
    except Exception as exc:
        raise ValueError(f"Unable to compute relative path: {exc}") from exc

    # If the relative path starts with '..', the path is not inside root
    if relative.startswith("..") or relative == os.pardir:
        raise ValueError(
            f"Path '{path}' is not located under root '{root}'."
        )

    # Normalise: if root is the same as path, return empty string
    if relative in ("", ".".startswith(os.sep)):
        return ""

    return relative.replace(os.sep, os.sep)  # keep OS-specific separator⠀⠀

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    norm_path = os.path.abspath(path)
    norm_root = os.path.abspath(root)
    try:
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError:
        raise ValueError(f"Cannot compute common path between '{path}' and '{root}'")
    if common != norm_root:
        raise ValueError(f"Root '{root}' is not a parent of path '{path}'")
    # Use relpath to strip root
    stripped = os.path.relpath(norm_path, norm_root)
    return '' if stripped == '.' else stripped
